(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["image"]||{};var a=d["papers"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="paper-mixdq-memory-efficient-few-step-text-2024"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-1\">一 · 在线出图服务的显存墙：从一次请求说起</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-2\">二 · 少步采样把单步误差放大成最终误差</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-3\">三 · 模块间容忍度差异让统一比特两头不讨好</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-4\">四 · 反量化开销与访存节省的权衡没有免费午餐</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-5\">五 · 为什么非改不可：预算约束必须写成带模块粒度的形式</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-6\">六 · 旧方案的边界与本文要补的账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-7\">七 · 在线出图服务里，统一精度为什么先崩</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-8\">八 · 请求形态：提示词长度、CFG 分支与“个位数步”的时间账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-9\">九 · 并发与批大小：CFG 合并是批的第一性来源</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-10\">十 · SLO 与长尾：延迟目标如何反向限制负载</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-11\">十一 · 负载如何塑造量化方案：敏感度按模块而非全局</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-12\">十二 · 方案反过来限制负载：反量化开销与批的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-13\">十三 · 可核查的测量清单与失败模式</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-14\">十四 · 批上限、显存预算与长尾请求：MixDQ 配置在服务端的可行域</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-15\">十五 · 反量化路径上的核心 kernel：从权重加载到 MMA</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-16\">十六 · 数据类型档位：FP16/BF16、FP8 与 NVFP4 的误差结构</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-17\">十七 · 累加精度与误差：MMA 内部的隐藏变量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-18\">十八 · tcgen05、TMEM 与 2-SM MMA：低比特如何吃到硬件红利</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-19\">十九 · 把精度档位映射到 MixDQ 的模块预算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-20\">二十 · 量化配置在 Blackwell 上的失效边界与代价核算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-21\">二十一 · 显存账本的三个户头：权重、激活、解码峰值</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-22\">二十二 · 带宽瓶颈在哪：权重读取与激活搬运的两条曲线</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-23\">二十三 · 分页、压缩、复用、卸载：四个动作的边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-24\">二十四 · HBM3e 容量怎么算：一个可复算的预算表</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-25\">二十五 · 预算与 SLO 的耦合：批上限不是越大越好</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-26\">二十六 · 失败模式的显存侧表现</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-27\">二十七 · 批的构成：CFG 合并与显存预算的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-28\">二十八 · 连续批处理：把个位数步的请求拼进同一时间片</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-29\">二十九 · Chunked prefill 的扩散对应物：条件嵌入与解码的分段</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-30\">三十 · 优先级与抢占：敏感层回退作为降级手段</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-31\">三十一 · 分离式预填/解码：把 VAE 峰值挪出主干时间片</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-32\">三十二 · 尾延迟：批内最慢分支与解码尖峰的双重来源</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-33\">三十三 · 调度边界：量化省出的显存该喂给谁</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-34\">三十四 · 并行切分的四条轴与扩散推理的真实映射</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-35\">三十五 · NVLink 5 与 NVSwitch：把 All-Reduce 的代价算清楚</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-36\">三十六 · All-to-All 在扩散推理里的缺席与 NIXL 的角色</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-37\">三十七 · 通信成为瓶颈的三个判据与量化带来的变量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-38\">三十八 · VAE 解码段的并行与显存峰值核算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-39\">三十九 · 切分拓扑与量化配置的耦合边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-40\">四十 · 精度塌陷：从“指标正常”到“图崩了”的断层</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-41\">四十一 · OOM：预算约束漏掉 VAE 解码峰值</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-42\">四十二 · 批抖动：动态批与少步采样的相位冲突</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-43\">四十三 · 尾延迟：解码阶段是 P99 的主贡献者</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-44\">四十四 · 静默降级：没有报错的失败最贵</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-45\">四十五 · 量化配置的失效边界与线上诊断闭环</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-46\">四十六 · 口径的第一层：模型与负载形态决定了哪些数字才有意义</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-47\">四十七 · 硬件档位：材料没给，就必须把档位当成口径变量而非常数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-48\">四十八 · batch 与并发：CFG 合并是口径分水岭</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-49\">四十九 · 指标族：TTFT/TPOT 在扩散推理里要重新定义</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-50\">五十 · 哪些提升不可比：四类典型陷阱</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-51\">五十一 · 把口径写进容量规划：从数字到可执行判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-52\">五十二 · 迁移的第一道关：误差稀释假设是否成立</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-53\">五十三 · 模块边界重划：文本编码器、主干、VAE 的容忍度不可照搬</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-54\">五十四 · 硬件档位：反量化开销与原生低精度格式的错位</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-55\">五十五 · 哪些场景不该用这套方案</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-56\">五十六 · 规模上限的工程判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-57\">五十七 · 迁移边界：度量解耦配置在哪些管线上失效</button></li></ol></nav><figure class=\"diagram\" data-fig=\"paper-pipeline\"><svg style=\"max-width:584px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 584.1 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"502.1\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">文本编码器接收提示词并输出条件嵌入，该模块按敏感度配置较高比特以保条件…</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"502.1\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">主干网络在少步采样器中执行去噪迭代，权重与激活按混合精度配置逐层反量化…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"502.1\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">采样器在个位数步内完成从噪声到潜变量的映射，每步误差因步数少而被放大需…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"502.1\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">VAE 解码器把潜变量还原为像素图像，其峰值显存与量化误差单独评估并纳…</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"502.1\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">服务端按批合并 CFG 的正负分支以提升吞吐，量化后的显存节省用于增大…</text></svg><figcaption><b>流水线</b> · 从输入到输出的数据流；每一步的模块与代价在正文展开。</figcaption></figure>\n<h3 id=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-1\">一 · 在线出图服务的显存墙：从一次请求说起</h3>\n<p>设想一个面向设计工具的在线出图服务：用户提交一段提示词，期望在数秒内拿到一张图。服务端跑的是已经蒸馏到个位数步的文本到图像扩散模型，单请求的前向计算量并不大——采样步数被压到个位数后，去噪循环的矩阵乘总量相比原始几十步版本成倍下降。真正卡住吞吐的不是算力，而是显存。一次请求的显存足迹由三块拼成：文本编码器的条件嵌入、主干网络（UNet 或 DiT）在少步采样器中的权重与逐层激活、以及最后 VAE 解码到像素空间时的激活峰值。前两块随批大小线性增长，第三块在解码瞬间冲上峰值——潜变量被一次性放大到像素分辨率，中间特征图的通道数与空间尺寸同时抬升，峰值显存往往超过整个去噪阶段的总和。服务端的现实是：批大小被这条峰值线钉死，GPU 的算力利用率长期趴在低位，队列延迟随并发上升而恶化。要提吞吐，要么加卡，要么把权重和激活的位宽压下去。</p>\n<p>这就是低比特量化进入这条管线的动机。权重从 FP16/BF16 压到 FP8 甚至 4 bit，权重体积与读取带宽同步下降；激活量化则进一步压缩逐层中间结果。对显存受限的在线服务，量化节省出的显存可以直接兑换成更大的批大小或更高的并发数，这是比单纯降延迟更直接的吞吐杠杆。问题在于，扩散模型对量化误差的容忍度远低于分类网络：误差不是被一次前向吸收，而是在去噪迭代中反复注入。</p>\n\n<h3 id=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-2\">二 · 少步采样把单步误差放大成最终误差</h3>\n<p>旧方案的主流做法是统一比特宽度：整条管线用同一个位宽（典型是 W8A8 或 W4A16），配置一次、全局套用。这种做法在几十步采样的模型上尚可接受，因为每步注入的量化噪声会被后续多步的迭代平均稀释——单步误差像是被扔进一个长滤波器，最终图像的偏差被摊薄。少步采样改变了这个前提。步数压到个位数后，没有任何多余的迭代来平均误差，每一步的数值偏差几乎原样传递到潜变量，再经 VAE 解码放大为可见的画质退化。用一句话概括这个机制：误差累积的稀释因子与步数同阶，步数越少，单步误差对最终输出的权重越大。</p>\n<p>把这件事写成粗略的误差传递关系，设第 <em>t</em> 步的量化扰动为 <em>ε<sub>t</sub></em>，采样器对该扰动的传递增益为 <em>G<sub>t</sub></em>，则最终潜变量偏差近似为各步贡献之和：</p>\n<div class=\"formula\">$$\\delta x_0 \\approx \\sum_{t=1}^{T} G_t \\, \\varepsilon_t, \\quad T \\in \\{2,\\dots,9\\}$$</div>\n<p>当 <em>T</em> 很大时，求和中的各项在统计上相互抵消一部分；当 <em>T</em> 只有个位数，求和项数少、抵消弱，任何一步的 <em>ε<sub>t</sub></em> 偏大都会直接反映在 <em>δx<sub>0</sub></em> 上。这就是统一比特方案在少步模型上失效的数值根源：它假设误差可以被步数稀释，而这个假设在少步场景下不成立。工程上的代价很具体——为了保住画质，运维只能把全局位宽抬回 8 bit 甚至更高，显存节省随之蒸发，批大小回到被峰值线钉死的状态，量化的吞吐收益归零。</p>\n\n<h3 id=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-3\">三 · 模块间容忍度差异让统一比特两头不讨好</h3>\n<p>统一比特的第二个痛点在于它无视了模块间的敏感度差异。同一条管线里，文本编码器、主干网络、VAE 解码器对量化误差的响应完全不同。文本编码器输出的是条件嵌入，它决定语义对齐——提示词里的主体、属性、空间关系都编码在这组向量里，一旦条件嵌入被量化噪声污染，后续所有去噪步都在错误的条件下推进，错误是系统性的而非随机的。主干网络承担去噪迭代，它的敏感度随层而异：靠近输入输出的层与注意力中的某些投影对数值扰动更敏感，中间层则相对鲁棒。VAE 解码器把潜变量还原为像素，它的误差直接体现为纹理、边缘与色彩的失真，而且它的激活峰值显存独立于主干——只压主干权重根本碰不到这块峰值。</p>\n<p>统一比特在这三者之间被迫折中：按最敏感的模块定档，不敏感模块的显存压缩空间被浪费；按最鲁棒的模块定档，敏感模块的画质塌方。这就是论文要解决的配置问题——不是“能不能量化”，而是“每个模块各给多少比特”。旧方案的失败模式可以列成一张对照表：</p>\n<table class=\"mini\"><thead><tr><th>模块</th><th>误差影响的性质</th><th>统一比特下的后果</th><th>显存角色</th></tr></thead><tbody><tr><td>文本编码器</td><td>系统性污染条件嵌入，语义漂移</td><td>全局降档时首当其冲，提示词遵循度下降</td><td>权重占比小，压缩收益有限</td></tr><tr><td>主干网络</td><td>逐层注入，少步下不被稀释</td><td>敏感层误差直接放大到潜变量</td><td>权重体积主体，压缩主战场</td></tr><tr><td>VAE 解码器</td><td>直接映射为像素失真</td><td>与主干同档时画质退化明显</td><td>激活峰值独立核算，常被忽略</td></tr></tbody></table>\n<p>这张表暴露的工程判断是：显存预算必须按模块分别核算，尤其要把 VAE 解码的激活峰值纳入约束，而不是只盯主干权重体积。旧方案把整条管线当成一个黑盒定一个位宽，等于放弃了按敏感度重新分配预算的全部空间。</p>\n\n<h3 id=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-4\">四 · 反量化开销与访存节省的权衡没有免费午餐</h3>\n<p>低比特推理不是把权重存小就完事。推理时权重以低位宽加载，进入矩阵乘与注意力计算前要逐层反量化回计算精度，这引入额外的指令与寄存器压力。旧方案在统一比特下做这笔账时，往往只看到访存带宽的节省，忽略了反量化在计算路径上的插入成本。对显存受限、算力有余的在线服务，这笔交易通常是划算的——省下的带宽和显存换来的批大小提升，摊薄了每请求的权重读取开销。但划算与否取决于批的组织方式。</p>\n<p>服务端有一个现成的摊薄手段：CFG（无分类器引导）的正负分支可以合并为一个批。CFG 要求每步同时评估条件与无条件两条路径，若串行执行，权重要被读取两遍；合并成一个批后，一次权重读取服务两条分支，权重读取开销被摊薄一半。量化节省出的显存正好用来容纳这个合并后的批，或进一步提高并发批数。这里的代价链条是清晰的：位宽下降 → 权重与激活显存下降 → 批上限抬高 → 权重读取摊销到更多样本 → 吞吐上升；而反量化开销随批大小被稀释，单请求延迟的增量在批吞吐面前可以接受。旧方案的问题不在于不懂这个链条，而在于统一比特把位宽锁死，无法在“哪些层值得为反量化付出计算、哪些层可以压到极低”之间做精细取舍。</p>\n\n<h3 id=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-5\">五 · 为什么非改不可：预算约束必须写成带模块粒度的形式</h3>\n<p>把上述痛点收拢成一个配置问题，旧方案的本质是求解一个退化的优化：只有一个位宽变量 <em>b</em>，目标是在画质与显存之间找折中点，而画质对 <em>b</em> 的响应在不同模块上方向不一致，单变量根本无法表达这种结构。论文的做法是把位宽变成按模块的向量 <em>{b<sub>l</sub>}</em>，并把误差度量拆成感知度量与重建度量两项，用加权和指导分配，同时把显存预算写成覆盖主干权重与 VAE 解码激活峰值的约束：</p>\n<div class=\"formula\">$$\\min_{\\{b_l\\}} \\; \\mathcal{L}_{\\text{percept}}(\\hat{x}(\\{b_l\\})) + \\lambda \\, \\mathcal{L}_{\\text{recon}}(\\{b_l\\}), \\quad \\text{s.t.} \\; \\sum_l \\text{mem}(b_l) \\le M$$</div>\n<p>这个式子的工程含义比它的数学形式更重要。第一，约束里的 <em>mem(b<sub>l</sub>)</em> 按模块求和，意味着 VAE 解码的激活峰值和主干权重进入同一个预算池，只压主干会在解码阶段撞墙——这是旧方案最典型的翻车方式：权重压下去了，批大小却没提上去，因为峰值转移到了 VAE。第二，目标函数的两项解耦，感知度量管最终画质，重建度量管数值保真，二者对不同模块的敏感度不同，解耦后才能让文本编码器和 VAE 拿到与主干不同的位宽。第三，<em>λ</em> 是显式的折中旋钮，服务端可以按 SLO 调——画质优先就抬感知项的权重，吞吐优先就在可接受画质下压预算。</p>\n<p>旧方案之所以非改不可，还因为少步采样已经把计算量压到个位数步，量化成为进一步降显存、提批吞吐的主要手段；如果量化只能在统一比特下做，这条手段就被画质红线封死。一个具体的判断场景：某敏感层在统一 4 bit 下画质塌方，运维把全局位宽抬到 8 bit，显存节省减半，批大小回到原点；而按模块分配时，这一层保留 8 bit、其余层压到 4 bit 甚至更低，预算约束仍能满足，批大小得以抬高。这就是配置框架相对统一比特的全部价值所在——它把“要不要量化”的二选一，换成了“每个模块各给多少”的分配问题。</p>\n\n<h3 id=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-6\">六 · 旧方案的边界与本文要补的账</h3>\n<p>需要说清楚的是，这篇论文的贡献落在配置框架，而非硬件部署。材料没有给出校准集规模、比特候选集合、搜索迭代次数，也没有给出 FID、CLIP 分数、显存占用与吞吐的定量结果，更没有与 NVFP4/FP8 等 Blackwell 原生低精度格式的对照，也没有 B200/GB200 档位上的实测。这意味着在 SM100/SM103 上落地时，还有几笔账要单独补：低精度算子的实际支持档位、并行切分对显存峰值的影响、以及反量化开销在 tcgen05 与 TMEM 路径上的真实代价。旧方案的痛点已经被定位清楚——少步放大单步误差、模块容忍度分化、VAE 峰值被忽略、统一比特锁死分配空间——而配置框架给出的是一条按模块分配精度的路径；这条路径能否在 Blackwell 上兑现成吞吐，取决于上述实测账目能否补齐。</p>\n\n<h3 id=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-7\">七 · 在线出图服务里，统一精度为什么先崩</h3>\n<p>设想一个挂在 GB200 NVL72 上的文生图在线服务：提示词进来，文本编码器出条件嵌入，少步采样器在个位数步内完成去噪，VAE 解码回像素。请求方按 SLO 等首图，服务端却卡在一个尴尬的折点上——单请求计算量已被少步蒸馏压得很小，延迟不再由 FLOPs 主导，而是由权重驻留与激活峰值主导。此时工程上最自然的做法是统一低比特：整网一个位宽，加载即压缩，吞吐立刻上去。但这套做法在少步管线上失效得很干脆：步数只有个位数，单步量化误差不会被后续几十步的迭代平均稀释，每一层的数值偏差都直接写进最终潜变量；而文本编码器、主干、VAE 三者对误差的容忍度根本不在一个量级，统一位宽等于把最敏感模块的精度预算浪费在最不敏感模块上。</p>\n<p>代价可以写成一条显存预算的硬约束。设模块 <span>l</span> 的位宽为 <span>b_l</span>，统一方案即所有 <span>b_l = b</span>，其可行域被最敏感模块卡死：为了让主干在个位数步下不糊，<span>b</span> 被迫抬到主干能接受的水平，文本编码器与 VAE 跟着一起付显存。服务端于是出现两种典型失效：一是批大小上不去，CFG 正负分支合并后仍受权重驻留挤压，队列延迟随并发线性恶化；二是只压主干权重、忽略 VAE 解码激活峰值，权重省下的显存被解码阶段一次性吃掉，长提示词或高分辨率下直接触发溢出回退。前者是吞吐损失，后者是可用性事故，二者都不是调调度能救的。</p>\n<div class=\"formula\">$$\\text{mem}_{\\text{total}} = \\sum_l \\text{mem}(b_l) + \\text{peak}_{\\text{VAE}}, \\quad \\text{s.t.} \\; \\text{mem}_{\\text{total}} \\le M$$</div>\n<p>把这条约束摊开看，统一精度的根本问题不是“不够低”，而是“不能分”。它没有表达力去说“文本编码器保高位、主干敏感层保中位、VAE 单独核算峰值”，只能整网同进退。于是旧方案在保真度与显存之间被迫折中：抬位宽则批小、吞吐低、单位请求功耗高；压位宽则少步采样下单步误差放大，出图质量掉到不可交付。真正的边界在于，量化收益必须按模块敏感度切分，且预算约束要同时覆盖主干权重与解码激活——这正是度量解耦与按模块比特分配要解决的问题，其配置搜索与感知/重建两项度量的分工在后续小节展开。</p>\n<h3 id=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-8\">八 · 请求形态：提示词长度、CFG 分支与“个位数步”的时间账</h3>\n<p>少步文本到图像服务的请求单元是“一条提示词→一张图”，但它的负载形态与 LLM 请求有本质差别：单请求计算量被蒸馏压到个位数步后，<strong>时间轴不再是等长的 token 流，而是三段异构阶段</strong>——文本编码、主干去噪、VAE 解码。测量口径必须把这三段拆开计时，否则批大小的调整会掩盖真实瓶颈。文本编码器的开销随提示词 token 数近似线性增长，长提示词抬高条件嵌入阶段的激活占用；主干去噪在个位数步下每步都是一次完整的权重读取加矩阵乘/注意力，权重带宽而非算力是主约束；VAE 解码的激活峰值与批大小相乘，往往是显存溢出的第一现场。可核查的口径是：对每条请求记录 <em>t_text</em>、<em>t_denoise</em>（按步累加）、<em>t_vae</em>，以及三段各自的显存峰值，并按提示词长度分桶统计 P50/P99。少步模型的一个工程后果是：<em>t_denoise</em> 被压缩后，<em>t_vae</em> 在端到端延迟中的占比显著上升，任何只优化主干的方案都会在 SLO 上失分。</p>\n<div class=\"formula\">$$T_{\\text{e2e}} = t_{\\text{text}}(L) + S \\cdot t_{\\text{step}}(B, b_l) + t_{\\text{vae}}(B, H, W)$$</div>\n<p>其中 <em>S</em> 为个位数采样步数，<em>B</em> 为批大小，<em>b_l</em> 为逐层比特宽度。这个式子直接暴露了 MixDQ 的负载含义：<em>t_step</em> 随 <em>b_l</em> 下降而下降（访存节省），但 <em>t_vae</em> 对量化不敏感，因此比特分配若只压主干，端到端收益被 VAE 段稀释。具体例子：一个批内混有短提示词与长提示词时，文本编码阶段被最长序列拖成“木桶”，而主干与解码阶段则被批内最慢样本的显存峰值卡住——这正是长尾请求在扩散服务里的表现形态，与 LLM 的 prefill 长尾同构但阶段归属不同。</p>\n\n<h3 id=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-9\">九 · 并发与批大小：CFG 合并是批的第一性来源</h3>\n<p>Classifier-Free Guidance 让每个逻辑请求在主干里变成两条计算路径（正、负条件分支）。服务端把这两条分支合并进同一个批，是扩散推理批调度的默认动作：权重只读一次，两条分支共享同一份反量化后的权重，摊薄了权重带宽开销。因此“有效批大小”应定义为 <em>B_eff = B_req × 2</em>（开启 CFG 时），测量口径必须区分逻辑请求数与物理批槽数，否则吞吐数字会被高估一倍。量化在这里的作用是间接的：低位宽权重降低了每槽的权重占用，节省的显存被换成更大的 <em>B_req</em>，从而在固定显存预算下提高 <em>B_eff</em>。</p>\n<p>代价关系可以写成显存预算的分解：</p>\n<div class=\"formula\">$$M_{\\text{peak}} \\approx \\underbrace{\\text{mem}_{\\text{w}}(b_l)}_{\\text{权重}} + B_{\\text{eff}} \\cdot \\underbrace{\\big(a_{\\text{denoise}} + a_{\\text{vae}}\\big)}_{\\text{每槽激活峰值}} \\le M$$</div>\n<p>这个不等式是 MixDQ 把 VAE 解码纳入预算约束的直接理由：<em>a_vae</em> 与批大小线性相乘，若只按主干权重估算预算，解码阶段会突破 <em>M</em>。可核查口径是逐阶段采样显存（NVML 或框架自带的内存快照），记录 denoise 峰值与 vae 峰值两个数，而不是只记一个全局峰值。具体例子：当 <em>B_req</em> 从 1 提到 4、CFG 合并后 <em>B_eff</em>=8，若 <em>a_vae</em> 占每槽激活的一半以上，则解码峰值可能先于主干触顶，此时正确动作是降 <em>B_req</em> 或对 VAE 单独配置精度，而非继续压主干比特。</p>\n\n<h3 id=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-10\">十 · SLO 与长尾：延迟目标如何反向限制负载</h3>\n<p>扩散服务的 SLO 通常按端到端延迟的 P99 设定，而 P99 由长尾请求决定。长尾有三个来源：超长提示词（文本编码段拉长）、批内最慢槽（显存峰值或反量化开销抖动）、以及解码阶段的固定成本。少步采样把 <em>S</em> 压到个位数，意味着<strong>单步误差不被多步平均稀释</strong>，于是敏感层的比特回退成为质量 SLO 的一部分：当监控发现图像质量指标越界，回退动作是提高敏感模块位宽，而这会抬高 <em>t_step</em> 与权重显存，反过来压缩可用的 <em>B_eff</em>。这就是“方案反过来限制负载”的闭环：质量 SLO 紧→比特高→显存占用大→批小→吞吐低→排队延迟长→延迟 SLO 紧。</p>\n<p>可核查的测量口径包括：按提示词长度分桶的 P99 端到端延迟、按 <em>B_eff</em> 分桶的单步延迟、以及质量指标（材料未给出具体指标名，落地时按团队既定口径）与比特配置的联合记录。工程判断上，应把“批上限”设为显存预算与延迟 SLO 的联合约束，而不是单一维度：<em>B_max</em> = min(显存允许的槽数, 使 P99 延迟不越界的槽数)。具体例子：若长提示词桶的 P99 已贴近 SLO，则调度器应对该桶单独限流或缩短其批，而不是全局降批——全局降批会牺牲短提示词桶的吞吐，属于用平均换长尾的典型误判。</p>\n\n<h3 id=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-11\">十一 · 负载如何塑造量化方案：敏感度按模块而非全局</h3>\n<p>负载形态直接决定比特分配的重心。文本编码器承受的是条件保真压力，其输出嵌入直接决定语义对齐，长提示词场景下该段激活更大，压到极低比特的收益有限而风险集中；主干网络是权重带宽的主战场，个位数步下每步误差直达终图，敏感层必须保留较高位宽；VAE 解码的量化误差影响像素级重建，且其激活峰值与批大小相乘，是显存预算的硬约束项。MixDQ 的度量解耦正是把这两类误差分开：感知度量指导主干与文本侧的比特，重建度量指导 VAE 侧与数值保真，加权和目标在显存预算 <em>M</em> 下搜索。</p>\n<div class=\"formula\">$$\\min_{\\{b_l\\}} \\; \\mathcal{L}_{\\text{percept}} + \\lambda\\,\\mathcal{L}_{\\text{recon}} \\quad \\text{s.t.} \\; \\text{mem}_{\\text{w}}(b_l) + B_{\\text{eff}}\\cdot a_{\\text{vae}}(b_{\\text{vae}}) \\le M$$</div>\n<p>注意约束项里 <em>B_eff</em> 是负载变量：同一套比特配置在不同并发下可行性不同。这意味着量化配置不能离线一次定死，服务端需要按当前批上限重算预算，或在配置表里预置“低并发高保真”与“高并发高压缩”两档。代价是配置切换带来的权重重载或反量化路径切换开销，材料未给出该开销的实测数字，落地时应以权重加载时间与首请求延迟为口径测量。具体例子：夜间低峰可切到敏感层高位宽档以保质量，白天高峰切到压缩档以保吞吐，切换点由排队长度与显存水位共同触发。</p>\n\n<h3 id=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-12\">十二 · 方案反过来限制负载：反量化开销与批的耦合</h3>\n<p>低位宽权重加载、逐层反量化后参与矩阵乘与注意力计算，这条路径的代价不是零：反量化在每层每次前向都要执行，其开销与批大小弱相关、与层数线性相关。当 <em>B_eff</em> 较小时，反量化开销占比上升，量化带来的访存节省可能被计算侧开销部分抵消；当 <em>B_eff</em> 较大时，权重读取被摊薄，反量化相对摊薄后的权重带宽占比下降，量化收益才充分显现。这构成一个负载与方案的耦合：<strong>量化方案在小批下收益打折，在大批下收益放大</strong>，因此“量化后吞吐提升”的测量必须绑定批大小口径，否则不可比。</p>\n<p>可核查口径：固定 <em>B_eff</em> 扫描比特配置，记录单步延迟与显存峰值；再固定比特配置扫描 <em>B_eff</em>，记录吞吐与 P99。两组曲线交叉点即为该配置的“有效批下限”。具体例子：若某敏感层保留 8 bit 而其余层压到 4 bit，小批时反量化路径的分支判断与类型转换可能成为单步延迟的可见项，此时提高批比继续降比特更划算；反之在大批下继续降比特的边际收益更高。Blackwell 档位上的低精度算子支持与反量化实现方式（是否融合进 MMA 前的加载路径）材料未给出对照，落地需以实测曲线为准，不能把论文的配置框架直接当作性能承诺。</p>\n\n<h3 id=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-13\">十三 · 可核查的测量清单与失败模式</h3>\n<p>把上述口径收敛成一张可执行的清单，避免用单一吞吐数字掩盖阶段差异：</p>\n<table class=\"mini\"><thead><tr><th>测量项</th><th>口径</th><th>用途</th></tr></thead><tbody>\n<tr><td>分段延迟</td><td>t_text / t_denoise(按步) / t_vae，按提示词长度分桶 P50/P99</td><td>定位长尾归属阶段</td></tr>\n<tr><td>有效批大小</td><td>B_eff = B_req × CFG 分支数，记录物理槽数</td><td>吞吐可比性</td></tr>\n<tr><td>分段显存峰值</td><td>denoise 峰值与 vae 峰值分开采样</td><td>验证预算约束是否覆盖解码</td></tr>\n<tr><td>比特配置</td><td>逐模块位宽与 λ 取值随请求批次记录</td><td>质量-SLO 闭环回溯</td></tr>\n<tr><td>质量指标</td><td>按团队既定口径，与比特配置联合记录</td><td>敏感层回退触发</td></tr>\n</tbody></table>\n<p>失败模式有三类，均与负载口径相关。其一，把度量解耦当免费收益：λ 选择不当会让感知与重建此消彼长，在长提示词桶上表现为语义漂移而在短提示词桶上表现为纹理退化，必须按桶分别看质量指标。其二，忽略 VAE 解码峰值：只压主干权重，在高并发下解码阶段先溢出，表现为批上限被迫下调而主干显存仍有富余。其三，敏感层回退不充分：个位数步下单步误差直达终图，全局统一比特在敏感层上失效，需保留逐层敏感度评估并按负载档位切换配置。这三类失败都能通过上表的联合记录被提前发现——测量口径本身就是方案的一部分，而不是事后报表。</p>\n\n<h3 id=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-14\">十四 · 批上限、显存预算与长尾请求：MixDQ 配置在服务端的可行域</h3>\n<p>MixDQ 的比特分配搜索以显存预算 M 为硬约束，而 M 在服务端并非静态常量：它等于卡上可用显存减去运行时预留，且必须同时覆盖主干权重、逐层反量化产生的临时激活，以及 VAE 解码阶段的激活峰值。批大小 B 与预算的关系可写成一条可核查的约束式：</p>\n<div class=\"formula\">$$B \\cdot \\big(\\text{mem}_{\\text{act}}(b_l) + \\text{mem}_{\\text{peak}}^{\\text{VAE}}\\big) + \\text{mem}_{\\text{weight}}(\\{b_l\\}) \\le M$$</div>\n<p>式中权重项与批大小无关，激活项与 VAE 峰值项随 B 线性增长。这条式子决定了方案的第一个边界：量化把权重项压小后，剩余预算被激活项迅速吃掉，批大小的实际上限由 VAE 峰值而非主干权重决定。只优化主干位宽的配置在低并发下看不出问题，一旦把 CFG 正负分支合并进同一批、B 翻倍，解码阶段的激活峰值就会先撞上预算墙。测量口径必须分开记录三项：加载后的权重常驻显存、单请求去噪过程的激活高水位、以及 VAE 解码的独立峰值；三者混在一起统计会让“量化省了多少”无法归因。</p>\n<p>负载形态对方案的反向塑造体现在提示词长度分布上。文本编码器保留较高比特，其激活随提示词 token 数增长，长提示词请求会抬高条件嵌入阶段的显存占用，并把单请求延迟拉长；而少步采样把主干迭代压到个位数，主干延迟在总延迟中的占比下降，队列延迟更多由文本编码与 VAE 解码两端决定。于是 SLO 的设定不能只看平均步延迟，要按分位数口径测量：单请求端到端延迟的 p50 与 p99、批内最慢请求的完成时间、以及显存高水位的 p99。长尾请求——超长提示词、异常宽高比导致解码激活膨胀——会把 p99 显存推高，若批调度按平均值装箱，长尾请求进入批内即触发回退或溢出。工程判断是给批调度加一条按请求特征分桶的规则：长提示词与高分辨率请求单独成批或降低批上限，而不是与短请求混装摊薄权重读取。</p>\n<p>失效条件集中在两处。其一，λ 的取值把感知度量与重建度量做成此消彼长：偏向重建会让感知质量下滑，偏向感知则可能让某些层的数值误差在少步采样下直接放大到像素域，且个位数步数不给后续迭代平均误差的机会，敏感层回退不足时单步误差直达输出。其二，显存预算 M 若只按离线标定的固定值设定，忽略并发上升时激活项的线性增长与长尾请求的峰值抬升，配置在低载下通过、在高载下失效。可核查的做法是把 M 拆成权重常驻与按批伸缩两部分分别监控，超预算时优先回退敏感层位宽而非削减批大小，因为批大小直接对应吞吐，而位宽回退只损失保真度裕量。材料未给出 λ 取值、校准集规模与比特候选集合，也未给出 B200/GB200 档位上的显存与吞吐实测，因此上述约束式只能作为部署时的核算框架，具体系数须以实测高水位填入。</p>\n<h3 id=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-15\">十五 · 反量化路径上的核心 kernel：从权重加载到 MMA</h3>\n<p>MixDQ 在推理期只做一件事：把按模块配置好的低位宽权重加载进来，在每一层做反量化，然后送进矩阵乘与注意力。这条路径在 Blackwell 上不是一个抽象的“量化算子”，而是三个物理上分离的阶段：低位宽权重的全局访存、反量化到高精度的寄存器/共享内存转换、以及 Tensor Core 上的 MMA。三者的代价结构完全不同，决定了混合精度配置能否真正兑现显存收益。</p>\n<p>设某层权重位宽为 <span class=\"inline-math\">b_l</span>（4/8/16 等），权重元素数为 <span class=\"inline-math\">N_l</span>，则加载该层权重的字节数为 <span class=\"inline-math\">\\(N_l \\cdot b_l / 8\\)</span>。反量化把它展开为 FP16/BF16 参与计算，中间张量的字节数为 <span class=\"inline-math\">\\(N_l \\cdot 16 / 8\\)</span>。也就是说，反量化在片上把访存节省“还回去”了一部分——省下的是 HBM 带宽，付出的是寄存器与共享内存的占用，以及一次逐元素的乘加（scale/zero-point 应用）。对 MixDQ 而言，敏感模块保留高比特意味着这些层几乎不产生访存收益，而它们恰恰是主干里计算最密集的部分，所以整体吞吐提升主要来自不敏感层与 VAE 的压缩，而非全模型均匀压缩。</p>\n<p>工程上的判断是：反量化的开销必须被 MMA 的算术强度掩盖。若某层是访存受限的（例如注意力里的 QKV 投影在小批下），反量化引入的额外指令会直接抬高延迟；若某层是计算受限的（大矩阵乘），反量化的逐元素开销可以被 Tensor Core 的长流水线吸收。因此混合精度配置在搜索时若只按“显存预算”排序，而不区分层的算术强度，落到 Blackwell 上会出现“显存省了、延迟没降”的错配。一个具体例子：主干中通道数很大的 FFN 层压到 4 bit 后，权重读取字节数减半，但反量化后的 FP16 中间张量仍占满共享内存，此时批大小受片上容量而非 HBM 限制，压缩收益被截断。</p>\n\n<h3 id=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-16\">十六 · 数据类型档位：FP16/BF16、FP8 与 NVFP4 的误差结构</h3>\n<p>Blackwell 的第五代 Tensor Core 原生支持 FP16/BF16、FP8（E4M3/E5M2）与 NVFP4 等档位，它们的误差结构差异决定了 MixDQ 的比特分配该落在哪一档。FP16 有 10 位尾数，BF16 只有 7 位尾数但动态范围与 FP32 相同；FP8 E4M3 有 3 位尾数与 4 位指数，NVFP4 则是 2 位尾数、2 位指数加一个块级缩放因子（每 16 个元素共享一个 FP8 scale）。</p>\n<p>对扩散模型而言，关键不是绝对精度而是相对误差在去噪轨迹上的传播。设某层量化后的权重为 <span class=\"inline-math\">\\(\\hat{W} = s \\cdot q\\)</span>，其中 <span class=\"inline-math\">q</span> 是低位宽整数或浮点码字，<span class=\"inline-math\">s</span> 是缩放因子，则该层输出的相对误差近似为 <span class=\"inline-math\">\\(\\|\\Delta y\\| / \\|y\\| \\approx \\|\\Delta W\\| / \\|W\\| + \\|\\Delta x\\| / \\|x\\|\\)</span>，即权重误差与激活误差可加。NVFP4 的块级缩放把 <span class=\"inline-math\">s</span> 从 per-tensor 细化到 per-block，显著压低了 <span class=\"inline-math\">\\(\\|\\Delta W\\|/\\|W\\|\\)</span> 中的离群值贡献——这正是它相对 INT4 per-tensor 的优势来源。但 2 位尾数意味着即使缩放完美，量化台阶仍然粗糙，对激活动态范围大的层（如注意力 softmax 前的 logits）不友好。</p>\n<p>MixDQ 的度量解耦在这里获得硬件含义：感知度量对纹理与高频细节敏感，对应的是主干后段与 VAE 解码；重建度量对数值偏差敏感，对应的是文本编码器输出与主干前段的条件注入。前者可以承受 NVFP4 的粗台阶（感知上高频误差被视觉系统容忍），后者需要 FP8 甚至 BF16 来维持条件嵌入的语义保真。代价上，NVFP4 相对 FP8 把权重字节数再减半，但块级缩放因子本身占额外字节（每 16 元素一个 FP8 scale，约 6% 开销），净压缩率不是严格的 2 倍；同时反量化需要先解块缩放再展开，指令数高于 FP8 的 per-tensor 反量化。</p>\n<table class=\"mini\"><thead><tr><th>档位</th><th>尾数/指数</th><th>缩放粒度</th><th>推理系统代价</th></tr></thead><tbody><tr><td>BF16</td><td>7 / 8</td><td>无</td><td>无收益，仅作敏感层回退档</td></tr><tr><td>FP8 E4M3</td><td>3 / 4</td><td>per-tensor 或 per-channel</td><td>权重减半，反量化廉价</td></tr><tr><td>NVFP4</td><td>2 / 2</td><td>per-16 块 FP8 scale</td><td>权重再减半，反量化指令增多</td></tr></tbody></table>\n\n<h3 id=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-17\">十七 · 累加精度与误差：MMA 内部的隐藏变量</h3>\n<p>低精度输入并不等于低精度输出。Blackwell Tensor Core 在 FP8 与 NVFP4 MMA 中使用 FP32 累加器，这一条对 MixDQ 的误差分析至关重要：权重与激活的量化误差在乘加树中被累加器吸收，不会像低精度累加那样随 K 维长度线性放大。设矩阵乘的 K 维长度为 <span class=\"inline-math\">K</span>，输入量化误差为 <span class=\"inline-math\">\\(\\epsilon\\)</span>，则输出误差的上界在 FP32 累加下约为 <span class=\"inline-math\">\\(O(\\sqrt{K}\\,\\epsilon)\\)</span>（随机误差假设），而在 FP16 累加下会退化为 <span class=\"inline-math\">\\(O(K\\,\\epsilon)\\)</span> 并叠加累加舍入。这就是为什么同一份 4 bit 权重，配 FP32 累加器可用、配低精度累加器不可用。</p>\n<p>但累加精度不是免费的：FP32 累加器在 MMA 流水线中占用更多寄存器与累加器存储，限制了同时驻留的 MMA tile 数量，进而影响 Tensor Core 的占用率。对 MixDQ 的混合精度配置，这意味着高位宽敏感层（BF16/FP8）与低位宽不敏感层（NVFP4）在同一 kernel 内混跑时，累加器宽度必须按最保守的层来定，否则误差会从低位宽层渗入。工程做法是按层分 kernel 或按块分组，让累加精度跟随该层的比特档位，而不是全模型统一。</p>\n<p>另一个被忽视的误差源是反量化后的中间张量精度。若权重从 NVFP4 反量化到 BF16 再进 MMA，BF16 的 7 位尾数会引入第二次舍入，与量化误差叠加。更优路径是让 MMA 直接消费 NVFP4 码字与块缩放，由 Tensor Core 内部完成解块——这正是 Blackwell 原生低精度格式的价值，也是 MixDQ 材料中“缺少与 NVFP4/FP8 对照数据”所指向的落地缺口：论文的配置框架没有绑定具体格式，实际误差取决于反量化路径是否绕过了中间高精度展开。</p>\n<div class=\"formula\">$$\\|\\Delta y\\| \\lesssim \\sqrt{K}\\,\\epsilon_{W} + \\sqrt{K}\\,\\epsilon_{x} + \\epsilon_{\\text{acc}}, \\quad \\epsilon_{\\text{acc}} \\propto 2^{-p_{\\text{acc}}}$$</div>\n<p>公式逐项：第一项是权重量化误差经 K 维累加的随机游走放大；第二项是激活量化误差的同构贡献；第三项是累加器精度 <span class=\"inline-math\">\\(p_{\\text{acc}}\\)</span> 带来的舍入底噪。三项中前两项由比特档位决定，第三项由硬件累加器决定。MixDQ 的比特分配实际上是在前两项之间做权衡，而第三项是 Blackwell 给出的固定红利——FP32 累加让前两项成为主导，从而使“按模块分配比特”的搜索有意义；若累加精度低，全局误差被第三项淹没，精细的模块级分配就失去分辨力。</p>\n\n<h3 id=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-18\">十八 · tcgen05、TMEM 与 2-SM MMA：低比特如何吃到硬件红利</h3>\n<p>Blackwell 的 tcgen05 指令族把 MMA 的累加器从寄存器文件搬到了 TMEM（Tensor Memory），这是一块与 Tensor Core 紧耦合的片上存储。对 MixDQ 的直接含义是：反量化后的操作数不再需要挤占寄存器文件，累加结果驻留 TMEM，寄存器压力下降，从而允许更大的 tile 与更高的占用率。低比特权重的收益因此从“省 HBM 带宽”扩展到“省寄存器”，后者在批大小受片上资源限制时才是真正的瓶颈。</p>\n<p>2-SM MMA 是另一条杠杆：两个 SM 协同执行一个 MMA，共享操作数与累加器，等价于把单个 MMA 的 M 维或 N 维加倍。对混合精度配置而言，2-SM 模式让高位宽敏感层（BF16/FP8）能以更大 tile 运行而不牺牲占用率，缓解了“敏感层保留高比特就拖慢整体”的担忧。代价是 2-SM MMA 要求两个 SM 的权重与激活分片严格对齐，若某层因比特宽度不同导致分片字节数不匹配（例如一侧 NVFP4、一侧 FP8），就无法配对，只能退回单 SM 路径。这构成一条硬约束：MixDQ 的模块级比特分配在 2-SM 拓扑下不能任意混搭相邻层，需按分片对齐分组。</p>\n<p>具体例子：主干的注意力输出投影若配置为 FP8，而相邻 FFN 配置为 NVFP4，两者在 2-SM 配对时字节数不一致，kernel 调度器会把它们拆成两次单 SM MMA，Tensor Core 占用率下降，吞吐收益被抵消。此时更优的做法是把同字节宽度的层聚成一组，让 2-SM 配对成立，再在组内做比特微调。显存侧，TMEM 的容量固定，累加器 tile 越大，同时驻留的 MMA 越少，批大小与 tile 尺寸之间存在显式折中，需在容量规划时与 KV/激活峰值一起核算。</p>\n\n<h3 id=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-19\">十九 · 把精度档位映射到 MixDQ 的模块预算</h3>\n<p>把上述硬件事实翻译成 MixDQ 的配置语言：文本编码器输出条件嵌入，语义敏感、层数少、计算量占比低，保留 BF16 或 FP8 的代价可接受，因为它的显存占比小，压缩它换来的预算不足以抵消语义退化。主干网络是显存与计算的主体，其前段（条件注入、早期去噪）对重建度量敏感，宜用 FP8；后段与 FFN 大矩阵对感知度量主导，可下探到 NVFP4，但需保证 FP32 累加与块缩放对齐。VAE 解码的激活峰值独立核算，其卷积层可用 FP8 甚至 NVFP4，但解码阶段的显存峰值往往由激活而非权重决定，压缩权重对峰值的缓解有限——这正是材料强调“预算约束必须覆盖解码激活”的硬件原因。</p>\n<p>少步采样放大了这一映射的紧迫性：个位数步数下，单步误差不被多步平均稀释，前段一次 FP8 的舍入会直接进入最终图像。因此“前段高比特、后段低比特”的分配不是审美偏好，而是误差传播路径的必然结果。代价上，前段高比特使这部分权重访存不降，主干的显存节省主要来自后段与 FFN；若后段占比不足，整体压缩率受限，此时应把 VAE 纳入压缩范围并在解码峰值上做批大小回退，而不是继续压前段。</p>\n<p>最后落在一条工程判断上：MixDQ 的度量解耦给出的是“哪些层可以降”的排序，而 Blackwell 的 tcgen05/2-SM/TMEM 给出的是“降了之后能不能兑现”的约束。两者交汇处是分片字节对齐与累加器宽度——配置搜索若不在目标硬件上以这两个量为约束重跑一遍，得到的比特表在 B200 上可能既省不了显存也提不了吞吐。可操作的落地方式是：先按字节宽度把层聚成 2-SM 可配对的组，再在组内用感知/重建两项度量做比特微调，最后用解码峰值显存反推批上限，把 VAE 的激活预算作为硬约束写进搜索。</p>\n\n<h3 id=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-20\">二十 · 量化配置在 Blackwell 上的失效边界与代价核算</h3>\n<p>MixDQ 的比特分配目标是一个带显存预算约束的加权和：<div class=\"formula\">$$\\min_{\\{b_l\\}} \\; \\mathcal{L}_{\\text{percept}}(\\hat{x}(\\{b_l\\})) + \\lambda \\, \\mathcal{L}_{\\text{recon}}(\\{b_l\\}), \\quad \\text{s.t.} \\; \\sum_l \\text{mem}(b_l) \\le M$$</div>其中 <em>b_l</em> 是第 <em>l</em> 个模块（文本编码器、主干、VAE 解码器）的权重/激活位宽组合，<em>mem(b_l)</em> 必须同时计入主干权重体积与 VAE 解码的激活峰值——只压主干权重、把解码峰值留在预算外，是这套配置最典型的失效方式：权重省下的显存被解码激活吃掉，批大小上不去，吞吐收益归零。λ 控制感知度量与重建度量的折中，材料未给出取值，这意味着部署时必须按目标 SLO 自行标定，λ 偏大偏向数值重建、偏小偏向感知质量，两者此消彼长而非免费收益。</p>\n<p>落到 Blackwell 的算子层面，这套混合精度配置的边界来自精度档位与累加路径的不匹配。逐层反量化后参与矩阵乘与注意力计算，若反量化结果喂给 FP8 或 NVFP4 的 tcgen05 MMA，累加仍在 FP32 累加器与 TMEM 中完成，量化误差不会被累加精度放大，但反量化本身的转换开销与访存节省的权衡材料未给出实测；若把敏感层压到极低位宽，单步误差在个位数步数下不被后续多步平均稀释，直接反映到最终图像，这正是敏感层必须回退高位宽的机制原因。2-SM MMA 与第五代 Tensor Core 提升的是单次矩阵乘的吞吐，并不能补偿比特配置错误带来的保真度损失，因此硬件档位只改变代价曲线、不改变失效边界。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>机制</th><th>系统代价</th></tr></thead><tbody><tr><td>预算未覆盖 VAE 解码峰值</td><td>权重压缩后解码激活仍超限</td><td>批大小无法提升，吞吐不增</td></tr><tr><td>敏感层位宽回退不足</td><td>少步采样放大单步误差</td><td>感知质量下降，需重跑搜索</td></tr><tr><td>λ 标定偏离 SLO</td><td>感知与重建度量此消彼长</td><td>质量或数值稳定性单边受损</td></tr><tr><td>反量化开销未计入</td><td>转换指令挤占 MMA 流水</td><td>单步延迟上升，抵消访存节省</td></tr></tbody></table>\n<p>工程判断上，CFG 正负分支合并为一个批摊薄权重读取开销，是量化节省显存后最直接的吞吐杠杆；但合并批会同步抬高激活峰值，与 VAE 解码的峰值核算叠加，预算 M 必须按“主干权重 + 合并批激活 + 解码峰值”三项联合约束来定，而非逐项独立优化。材料未给出与 NVFP4/FP8 原生格式的对照数据，因此把 MixDQ 的配置直接映射到 B200/GB200 档位前，需先实测反量化路径在 tcgen05 上的实际吞吐与逐层敏感度回退的触发阈值。</p>\n<h3 id=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-21\">二十一 · 显存账本的三个户头：权重、激活、解码峰值</h3>\n<p>在少步扩散服务里，显存不是一笔糊涂账，而是一本三栏账本：<strong>常驻权重</strong>、<strong>去噪迭代中的激活</strong>、<strong>VAE 解码的瞬时峰值</strong>。MixDQ 的预算约束写作 <span class=\"formula\">$$\\sum_l \\text{mem}(b_l) \\le M$$</span>，其中 mem(b_l) 按模块粒度累加，且 M 必须同时覆盖主干权重与 VAE 解码的激活峰值——这是该方法与“只压缩主干权重”的量化方案在账本口径上的根本区别。文本编码器输出条件嵌入后即完成使命，其权重可视为一次性读取；主干在个位数步内反复读取全部权重，是带宽与容量的双重压力点；VAE 解码只跑一次，却因为要把潜变量铺回像素空间而产生远高于单步去噪的激活峰值。工程上要先把这三栏分开记，再谈压缩。</p>\n<p>一个可复算的例子：设主干为 DiT，参数量 N，权重以 b 比特存放，则权重体积 <span class=\"formula\">$$W = \\frac{N \\cdot b}{8}\\ \\text{bytes}$$</span>。若 N 取 2×10⁹ 量级、b=4，则 W≈1 GB；若统一 16 比特则约 4 GB。差额 3 GB 就是量化释放出来的“批预算”。但激活峰值与批大小成正比，而 VAE 解码的峰值往往与批大小近似线性——把省下的 3 GB 全部押到批上，很可能在解码阶段撞墙。正确做法是把 M 拆成 M_w（权重）+ M_a（去噪激活）+ M_v（解码峰值）+ M_os（框架与通信缓冲），四者之和才是可承诺的显存上限。</p>\n<table class=\"mini\"><thead><tr><th>户头</th><th>随什么增长</th><th>压缩手段</th><th>代价落点</th></tr></thead><tbody><tr><td>权重</td><td>参数量 × 位宽</td><td>按模块混合精度、逐层反量化</td><td>反量化指令开销、访存节省的净收益</td></tr><tr><td>去噪激活</td><td>批大小 × 分辨率 × 层宽</td><td>按步复用、及时释放</td><td>重算或搬运带来的延迟</td></tr><tr><td>解码峰值</td><td>批大小 × 像素面积 × 通道</td><td>分块解码、批内串行解码</td><td>解码吞吐下降、尾延迟拉长</td></tr><tr><td>框架缓冲</td><td>批大小、并行度</td><td>固定池化、预分配</td><td>灵活性下降</td></tr></tbody></table>\n<p>注意：扩散推理没有自回归解码那种随序列增长的 KV cache。材料明确指出“KV 策略不适用于扩散推理”，潜变量与中间激活按步复用并及时释放。因此本部分谈“KV”时，指的是广义的<strong>中间态缓存</strong>——跨步复用的潜变量、CFG 双分支的激活、以及 VAE 解码的分块缓冲，而不是 Transformer 的 key/value 张量。把 LLM 那套分页 KV 管理直接搬过来是常见误判。</p>\n\n<h3 id=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-22\">二十二 · 带宽瓶颈在哪：权重读取与激活搬运的两条曲线</h3>\n<p>少步采样把计算量压到个位数步，单请求的算术强度随之下降，推理从“算力受限”滑向“带宽受限”。每步去噪都要把全部主干权重从 HBM 读进 SM，权重读取量 <span class=\"formula\">$$B_{\\text{step}} = \\frac{N \\cdot b}{8} \\times \\text{(每步读取次数)}$$</span>，再乘以步数 T 得到单请求的权重流量。T 越小，单步的固定权重读取越难被摊薄——这正是少步模型对量化位宽格外敏感的系统层原因：位宽减半，单步权重流量减半，而步数无法再减。</p>\n<p>第二条曲线是激活搬运。CFG 的正负分支若分开跑，等于把权重读两遍；材料给出的做法是把正负分支合并为一个批，摊薄权重读取开销。合并后批内两条样本共享同一次权重加载，权重流量不翻倍，但激活占用翻倍——这是一次典型的“用显存换带宽”的交易。在 B200 这类 HBM3e 容量充裕的档位上，这笔交易通常划算；在容量吃紧的切分拓扑上则要重新算。</p>\n<p>第三条曲线是反量化的开销。推理时以低位宽权重加载、逐层反量化后参与矩阵乘与注意力计算，反量化把“访存节省”部分转化为“指令开销”。材料未给出该权衡的实测数字，但工程判断是明确的：反量化必须是融合进 GEMM 主循环的逐元素操作，若退化为独立 kernel 写回中间张量，则既多了一次写又多了次读，带宽收益被吃掉。Blackwell 上 tcgen05 与 TMEM 的用法决定了这条路径是否顺畅——低位宽权重直接进 MMA 的通道越短，反量化的边际成本越低。</p>\n<p>具体例子：批大小 8、CFG 合并后实际批 16，主干权重 4 比特约 1 GB，单步权重读取约 1 GB；若 HBM3e 单卡带宽按档位取一个量级值，单步权重传输时间与单步计算时间同量级，说明此时系统确实卡在权重流上。把位宽从 8 降到 4，权重流量减半，单步时间中权重项近似减半——这就是少步场景下量化直接换吞吐的机制，而不是靠算力节省。</p>\n\n<h3 id=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-23\">二十三 · 分页、压缩、复用、卸载：四个动作的边界</h3>\n<p><strong>分页</strong>在扩散推理里主要落在 VAE 解码：把像素空间输出按 tile 切分，逐块解码、逐块写回，使解码峰值从“整幅图”降为“一个 tile 加若干行重叠”。分页的代价是重叠区的重复计算与边界拼接，tile 越小峰值越低、重复计算越多。工程上把 tile 尺寸当作一个可调参数，与批大小联动：批大则 tile 小，反之亦然，目标是让 M_v 落进预算。</p>\n<p><strong>压缩</strong>就是本方法的主题：按模块敏感度分配比特。文本编码器对语义敏感，保留较高位宽；主干中敏感层保留高位宽、不敏感层压到极低比特；VAE 解码单独配置。压缩的边界在于少步采样放大了单步误差——个位数步数下误差不被多步平均稀释，因此“全局统一低比特”在少步模型上必然失效，必须逐层评估敏感度。这与前文算子与数值精度部分讲的位宽选择是同一件事的显存侧投影，此处不重复格式细节。</p>\n<p><strong>复用</strong>指跨步复用不随步变化的量：条件嵌入在整个去噪过程中不变，应只计算一次并常驻；CFG 的正分支与负分支共享同一潜变量布局，可复用缓冲。复用的代价是常驻占用，需要与批大小争夺同一块显存。一个可操作的判断：凡是在 T 步中读取次数等于 T 且内容不变的对象，都值得常驻；凡是每步重算且体量小的对象，宁可重算不常驻。</p>\n<p><strong>卸载</strong>是把当前步不用的权重或缓冲搬到主机侧或对端。扩散推理的步间依赖是串行的，理论上可以流水：第 k 步计算时预取第 k+1 步所需权重。但权重是全量参与每步的，卸载主干权重等于每步都要一次 H2D 传输，PCIe 带宽远低于 HBM，这条路径只在权重明显大于可用显存时才有意义。更现实的是卸载文本编码器——它在条件嵌入产出后即闲置，把它的权重让给批缓冲是零延迟代价的显存回收。</p>\n<p>具体例子：单卡预算 M 中，文本编码器权重若占数百 MB 且只在前段使用，可在嵌入产出后释放并归还给激活池；这一步不改变任何数值结果，却直接抬高可支持的批上限。这类“时序性卸载”比“容量性卸载”划算得多，因为它不引入跨步传输。</p>\n\n<h3 id=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-24\">二十四 · HBM3e 容量怎么算：一个可复算的预算表</h3>\n<p>容量计算要区分“标称容量”与“可用容量”。标称容量扣除框架常驻、通信缓冲、碎片余量后才是可承诺的推理预算。工程上常用的经验拆分是：框架与运行时占一块固定值，通信与集合操作缓冲按并行度占一块，剩余部分按权重、激活、解码峰值三栏分配。材料未给出 B200/GB200 档位的实测数字，因此下面给的是结构而非数值——把每个符号替换成实测值即可复算。</p>\n<div class=\"formula\">$$M_{\\text{avail}} = M_{\\text{HBM}} - M_{\\text{rt}} - M_{\\text{comm}} - M_{\\text{frag}}$$</div>\n<div class=\"formula\">$$M_{\\text{avail}} \\ge \\underbrace{\\frac{N \\cdot b_w}{8}}_{W} + \\underbrace{c_a \\cdot B \\cdot S}_{A} + \\underbrace{c_v \\cdot B \\cdot P}_{V}$$</div>\n<p>其中 B 为批大小（CFG 合并后），S 为潜变量分辨率相关的激活系数，P 为像素面积相关的解码系数，c_a、c_v 为每单位批的字节系数，需实测标定。给定 b_w 与预算，可解出最大批：</p>\n<div class=\"formula\">$$B_{\\max} = \\left\\lfloor \\frac{M_{\\text{avail}} - W}{c_a S + c_v P} \\right\\rfloor$$</div>\n<p>这个式子的工程含义是：<strong>降低 b_w 只抬高分子，而分母由解码峰值主导时，批上限的提升会被 V 项吃掉。</strong>因此 MixDQ 把 VAE 解码峰值纳入预算约束不是形式主义——若只压主干权重，W 降了但 V 不变，B_max 的提升远小于预期，甚至因为解码阶段溢出而根本跑不到目标批。反过来，若对 VAE 解码做分块并单独配置精度，分母中的 c_v P 下降，批上限才真正打开。</p>\n<p>可复算例子：设 M_avail 归一化为 1，W 在 16 比特下占 0.4、4 比特下占 0.1；c_a S 每批 0.02，c_v P 每批 0.06。16 比特时 B_max = ⌊(1−0.4)/0.08⌋ = 7；4 比特时 B_max = ⌊(1−0.1)/0.08⌋ = 11。若同时对解码分块使 c_v P 降到 0.03，则 B_max = ⌊0.9/0.05⌋ = 18。可见单压权重只带来约 1.6 倍批提升，权重压缩叠加解码峰值压缩才带来约 2.6 倍——这就是“预算必须覆盖解码”的定量理由。上述系数为结构示例，落地时须以实测替换。</p>\n\n<h3 id=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-25\">二十五 · 预算与 SLO 的耦合：批上限不是越大越好</h3>\n<p>批上限由显存给出，但实际批大小由 SLO 给出。并发场景下队列延迟主要由单请求的采样步数与解码时间决定，批越大单请求延迟越高、吞吐越高，二者在尾延迟约束下取折中。少步模型的特殊性在于单请求计算量小，批的边际吞吐收益在低批时很陡、高批时趋缓，而解码时间随批近似线性增长——这意味着把批推到显存上限往往不划算，解码会成为尾延迟的长尾。</p>\n<p>工程判断：把批大小设为显存上限的一个比例，留出解码峰值的抖动余量；对解码做批内串行或分块并行，使解码不成为整批的同步屏障。监控项应包括单步延迟、显存峰值、批大小与图像质量指标，超预算时回退敏感层比特——材料列出的这条回退路径正是预算与保真度耦合的操作接口：显存峰值逼近上限时，先降不敏感层位宽，再降批，最后才动敏感层，因为少步采样下敏感层的误差不会被稀释。</p>\n<p>具体例子：CFG 合并把批从 B 变为 2B 的等效激活，但权重只读一次。若显存预算在解码阶段吃紧，可对正负分支做解码串行：去噪阶段合并批以摊薄权重读取，解码阶段拆回两条分别解码，峰值减半而权重流量不变。这是“分阶段改变批形态”的手法，比全局降批更精细。</p>\n\n<h3 id=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-26\">二十六 · 失败模式的显存侧表现</h3>\n<p>第一类失败是账本口径错误：只核算主干权重，把 VAE 解码峰值当作“运行时自然处理”。表现为批调大后偶发 OOM，且 OOM 总发生在解码而非去噪，日志上像是随机故障，实际是预算约束漏了一栏。修正方式是显式建模 M_v 并纳入搜索约束，与 MixDQ 的 mem(b_l) 口径一致。</p>\n<p>第二类失败是反量化路径未融合：低位宽权重加载后在独立 kernel 里反量化写回高精度缓冲，带宽收益被写回流量抵消，显存还多了一份临时缓冲。表现为位宽降了但单步延迟没降、显存反而涨。修正方式是把反量化压进 GEMM 主循环，让低位宽数据直接进 MMA 通路。</p>\n<p>第三类失败是敏感层回退不足：为追求显存把全局位宽压到极低，少步采样下单步误差直接反映到最终图像。表现为图像质量指标在低比特档断崖式下降，而非平缓退化。修正方式是逐层敏感度评估加按模块配置，而不是全局统一比特——这正是度量解耦框架要解决的问题，其感知度量与重建度量的加权系数 λ 需按目标 SLO 调，材料未给出具体取值。</p>\n<p>第四类失败是把分页 tile 设得过小：解码峰值降了，但重叠区重复计算使解码时间上升，尾延迟恶化。表现为显存达标而 SLO 不达标。修正方式是 tile 与批联动调参，并以解码时间为约束而非仅以峰值为约束。</p>\n<p>落到具体机制上：显存预算的可复算性来自把 W、A、V 三栏分别用实测系数标定，再用 B_max 公式反解批上限；而少步扩散的特殊性在于 T 小使权重流量无法被步数摊薄，因此位宽是吞吐的一阶杠杆，解码峰值是批上限的一阶杠杆，两者必须同时进预算，否则压缩收益会在解码阶段被抵消。</p>\n<h3 id=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-27\">二十七 · 批的构成：CFG 合并与显存预算的耦合</h3>\n<p>在少步文本到图像的服务端，批不是一个自由参数，而是被显存预算 M 与 CFG 结构共同决定的量。MixDQ 的配置搜索把预算约束写成 <span class=\"formula\">$$\\sum_l \\text{mem}(b_l) \\le M$$</span>，这里的 mem 同时覆盖主干权重与 VAE 解码的激活峰值——这一点直接改变了批调度的算法。常规 LLM 服务里，KV cache 随批线性增长，批上限由 KV 显存除以每序列 KV 字节数得到；扩散推理没有 KV，取而代之的是每步的中间激活与 VAE 解码的一次性峰值，因此批上限不是线性外推，而是要在“主干激活 × 批 + VAE 峰值”这个分段函数上求解。工程上的做法是把 CFG 的正负分支合并进同一个批：同一提示词的两个条件分支共享同一份权重读取，权重访存被摊薄一半，而激活侧只是把批维度翻倍。代价是批内两条分支必须同步推进，任一条分支的层反量化慢一拍就拖住整个批，因此 CFG 合并提升的是权重带宽利用率而非延迟。</p>\n<p>具体例子：一个主干被压到低位宽、文本编码器保留较高比特的配置下，权重体积下降释放出的显存被用于把批从 1 提到 2 并合并 CFG 分支，等效于单次前向处理两条条件流；而如果 VAE 解码器仍按高位宽配置，解码阶段的激活峰值会吃掉这部分节省，批上限回到 1。这说明批调度不能只看主干，必须把 VAE 峰值作为硬约束参与求解，否则调度器会在解码阶段触发溢出并回退批大小，形成吞吐抖动。</p>\n\n<h3 id=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-28\">二十八 · 连续批处理：把个位数步的请求拼进同一时间片</h3>\n<p>少步采样把单请求的计算量压到个位数步，单请求的绝对延迟很短，这使连续批处理（continuous batching）的收益结构与小步数强相关。传统批处理按“整批同步”推进：一批请求必须等最慢的那条完成全部步数才能释放槽位，槽位空转发生在批尾。连续批处理改为按步调度：每一步结束时检查队列，把已完成请求移出、把新请求插入空出的批槽，批的成员在步与步之间可以变化。对扩散管线而言，这要求采样器的状态（当前潜变量、步计数、条件嵌入）能按请求独立持有并在批内按槽位索引，而不是绑定在固定的批张量位置上。</p>\n<p>伪代码思路：调度循环在每次去噪步前执行 <code>slots = evict_finished(slots); slots = fill_from_queue(slots, budget)</code>，其中 budget 由当前显存余量决定，而显存余量要在“主干激活 + 待解码潜变量”两项上分别核算。由于步数只有个位数，单请求在批内停留的时间片极短，槽位周转率高，队列延迟主要由排队位置而非单请求执行时间决定。代价在调度器侧：每步一次槽位重排意味着条件嵌入需要按新槽位重新 gather，这个 gather 是显存带宽操作，批越大、重排越频繁，调度开销占单步时间的比例越高。工程判断是当单步时间被量化压缩到很小的时候，调度开销会成为吞吐的隐性上限，此时应降低重排频率或改用固定槽位加请求队列的折中方案。</p>\n\n<h3 id=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-29\">二十九 · Chunked prefill 的扩散对应物：条件嵌入与解码的分段</h3>\n<p>LLM 的 chunked prefill 把长 prompt 的预填切成块与解码请求混批，目的是压平 prefill 造成的延迟尖峰。扩散管线里没有等价的“长 prefill”，但有两个结构上同构的阶段：文本编码器的条件嵌入计算，以及 VAE 解码。文本编码器对长提示词的开销随长度上升，且这部分模块在 MixDQ 的配置里保留较高比特（语义敏感），其计算不能被量化压缩掉，因此长提示词请求会在条件嵌入阶段形成尖峰。把它切块并与去噪步混批，等价于把条件嵌入的 token 分片，每片与一个去噪步的时间片对齐，使尖峰被摊平到多个步上。</p>\n<p>VAE 解码则是另一个方向的尖峰：解码是一次性的大激活峰值，无法与去噪步混批，只能单独占一个时间片。调度上的处理是把解码排成独立的微批队列，与去噪批错峰执行，避免解码峰值与主干激活峰值叠加。代价是解码时间片内主干槽位空转，吞吐下降；收益是显存峰值不再叠加，批上限得以维持。这个取舍的判据是解码时间占单请求总时间的比例——比例越高，错峰造成的空转损失越大，越倾向于用更小的批换更平滑的峰值。</p>\n\n<h3 id=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-30\">三十 · 优先级与抢占：敏感层回退作为降级手段</h3>\n<p>MixDQ 的逐层比特配置给抢占提供了一个不常见但有效的维度：抢占不一定要丢弃请求，可以临时把某些层的位宽回退到更高精度以换取数值稳定，或者反向操作——在显存紧张时把不敏感层压到更低比特以腾出空间接纳高优先级请求。前者的代价是显存与带宽上升、吞吐下降；后者代价是图像质量下降。调度器需要把这两类降级与请求优先级绑定：高优先级请求走保真路径，低优先级请求走压缩路径，二者在同一批内共存时，按槽位分别配置反量化位宽，而不是整批统一。</p>\n<p>公式上可以把抢占判据写成单位显存换取的 SLO 满足率：<span class=\"formula\">$$\\text{preempt if} \\; \\frac{\\partial \\text{SLO}_{\\text{met}}}{\\partial \\text{mem}_{\\text{freed}}} \\big/ \\frac{\\partial \\text{quality}}{\\partial \\text{bits}} &gt; \\tau$$</span>，即释放单位显存带来的 SLO 改善超过位宽下调带来的质量损失阈值 τ 时才执行降级。这个判据要求调度器持有逐层敏感度评估结果——也就是配置搜索阶段产出的模块粒度比特分配，而不是全局统一比特。没有逐层敏感度，抢占只能整批降级，质量损失不可控。代价是调度器状态变复杂：每个槽位携带自己的位宽配置，反量化 kernel 需要按槽位分支，分支带来的指令开销在低位宽下不可忽略。</p>\n\n<h3 id=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-31\">三十一 · 分离式预填/解码：把 VAE 峰值挪出主干时间片</h3>\n<p>分离式（disaggregated）预填/解码在 LLM 里是把计算密集的 prefill 与访存密集的 decode 放到不同资源池。扩散管线的对应切分点不在文本编码器与主干之间，而在主干去噪与 VAE 解码之间：去噪阶段是反复的权重读取与矩阵乘，访存密集且批可合并；解码阶段是一次性的大激活、计算相对集中，且峰值显存与主干不共享。把这两段放到不同实例上，主干实例可以维持高批大小与稳定的权重带宽利用率，解码实例按峰值显存配置、批大小取小以避免叠加。中间传递的是潜变量张量，体积远小于像素输出，传输开销可接受。</p>\n<p>代价在传输与同步：潜变量需要在两个池之间搬运，跨节点时走 NVLink 5 或网络，延迟进入端到端关键路径；同时解码实例的利用率取决于潜变量到达的速率，主干批越大、解码实例越容易成为瓶颈，反之解码实例空转。容量规划的判据是两段的稳态吞吐比：主干实例数 × 单实例批吞吐 与 解码实例数 × 单实例解码吞吐 需匹配，否则一端积压。对 MixDQ 的配置而言，解码实例的显存预算要按高位宽 VAE 核算，量化节省的显存主要留给主干侧提批，这个不对称是分离式部署的直接后果。</p>\n\n<h3 id=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-32\">三十二 · 尾延迟：批内最慢分支与解码尖峰的双重来源</h3>\n<p>尾延迟在扩散服务里有两个独立来源，压法不同。第一个来源是批内最慢成员：CFG 合并后批内两条分支同步推进，任一条分支遇到长提示词或高位宽敏感层反量化慢，整个批的这一步就被拖住；连续批处理能缓解但不能消除，因为步内同步是硬约束。压法是把长提示词请求单独成批或降低其批内占比，使批内成员的步时间方差收敛。第二个来源是解码尖峰：解码时间片不与去噪重叠时，端到端延迟等于去噪时间加解码时间，解码的绝对时长直接进入尾延迟；错峰调度降低的是显存峰值而非延迟，两者不可兼得。</p>\n<p>工程判断落在批上限的设定上：批越大，权重读取摊薄越好、吞吐越高，但批内方差与解码排队同时放大尾延迟。SLO 若约束 P99 而非均值，批上限应由尾延迟反推而不是由显存反推——先定可接受的批内步时间方差与解码排队上限，再算显存是否支撑该批，若支撑不住则回到配置搜索收紧不敏感层位宽、释放显存换批。这个顺序与“先压显存再提批”的直觉相反，但对尾延迟敏感的服务是必要的：显存是手段，批是结果，尾延迟是约束。</p>\n\n<h3 id=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-33\">三十三 · 调度边界：量化省出的显存该喂给谁</h3>\n<p>MixDQ 的显存收益不落在单请求延迟上，而落在批容量上。逐层反量化让权重读取从低位宽存储中获益，但反量化本身引入额外指令与寄存器压力，单条请求的端到端时间未必缩短；真正的杠杆是把省出的显存换成更大的批。CFG 正负分支合并为一个批是这里最直接的动作：两分支共享同一份权重读取，权重带宽开销被摊薄一半，代价是批内序列长度翻倍、注意力激活同比上升。设主干权重显存为 <span class=\"formula\">$$W_q$$</span>、单请求激活峰值为 <span class=\"formula\">$$A$$</span>、VAE 解码峰值为 <span class=\"formula\">$$V$$</span>，则可行批大小近似为 <span class=\"formula\">$$B \\le \\lfloor (M - W_q - V) / A \\rfloor$$</span>。这个式子暴露了失效条件：若 VAE 峰值 V 未被压下去，分子被它吃掉，量化省出的显存再多也换不来批大小，连续批处理与 chunked prefill 的调度空间随之消失。</p>\n<p>由此产生一个调度判断：量化配置的搜索预算 M 必须把 VAE 解码激活计入，否则服务端会出现“主干能跑大 batch、解码阶段却 OOM”的错配。工程上的做法是把解码阶段单独设一个并发上限，让去噪阶段的连续批处理与解码阶段的串行化分离——去噪批可以大，解码批必须小，两者用不同的队列深度。这正是分离式预填/解码思路在扩散服务里的变体：不是拆 prefill 与 decode，而是拆去噪迭代与像素还原，前者吃算力与权重带宽，后者吃激活显存。</p>\n<p>尾延迟的压力来自少步采样本身。步数只有个位数，意味着单请求的延迟方差几乎全部由最慢那一步决定，任何一步的量化误差回退（敏感层临时提高位宽）都会直接抬高峰值而非被后续步平均掉。优先级与抢占因此不能按请求粒度做，必须按步粒度：高优先级请求在关键步上独占敏感层的高位宽通路，低优先级请求在该步被抢占、让出显存与带宽。代价是抢占带来的潜变量换出与重入，若潜变量常驻显存则抢占无意义，必须显式换出到主机侧，这又引入 PCIe 往返延迟。判断标准很硬：当单步延迟的 P99 超过 SLO 余量时，抢占换出的收益才成立；否则应改为降低批上限、牺牲吞吐保尾延迟。</p>\n<table class=\"mini\"><thead><tr><th>调度动作</th><th>收益</th><th>代价</th></tr></thead><tbody><tr><td>CFG 合并批</td><td>权重读取摊薄</td><td>激活翻倍，批上限下降</td></tr><tr><td>解码阶段独立限流</td><td>避免 VAE 峰值 OOM</td><td>解码串行，吞吐受限</td></tr><tr><td>按步抢占</td><td>压 P99 尾延迟</td><td>潜变量换出，PCIe 往返</td></tr></tbody></table>\n<h3 id=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-34\">三十四 · 并行切分的四条轴与扩散推理的真实映射</h3>\n<p>在 Blackwell 上谈并行，先要把 LLM 推理里那套 TP/EP/PP/DP 的直觉翻译成扩散推理管线的形状。MixDQ 这条管线是文本编码器 → 主干（UNet 或 DiT）少步去噪 → VAE 解码，三段对并行的友好程度完全不同。张量并行（TP）切的是单层内的矩阵乘与注意力头，对主干最自然：DiT 的每个 block 里 QKV 投影与 FFN 都是大矩阵，按列或按行切分后每张卡只持有 1/N 的权重分片，配合 tcgen05 的 2-SM MMA 还能让一对 SM 协同完成一次更大的 MMA，把分片后的 tile 尺寸重新拉回硬件甜点区。流水并行（PP）切的是层，对少步采样是个陷阱：步数只有个位数，PP 的 stage 间气泡无法靠“多步”摊薄，micro-batch 数量受显存约束又上不去，气泡占比会直接吃掉并行收益。专家并行（EP）只在主干是 MoE 结构时才有意义，扩散主干通常不是，这条轴在本方法里基本闲置。数据并行（DP）切的是请求，是服务端最省事的一档：每张卡持有完整权重、各自跑不同 prompt，权重读取被多请求摊薄，代价是权重显存不下降——而 MixDQ 的整个动机恰恰是权重与激活的显存占用，DP 帮不上这个忙。</p>\n<p>于是本方法落地时的实际组合是：TP 用于主干与文本编码器，DP 用于跨副本扩吞吐，PP 仅在单卡放不下主干时才被迫启用，VAE 解码器单独成段、不参与主干的 TP 分组。这个划分的判据是显存预算约束本身：</p>\n<div class=\"formula\">$$\\min_{\\{b_l\\}} \\; \\mathcal{L}_{\\text{percept}}(\\hat{x}(\\{b_l\\})) + \\lambda \\, \\mathcal{L}_{\\text{recon}}(\\{b_l\\}), \\quad \\text{s.t.} \\; \\sum_l \\text{mem}(b_l) \\le M$$</div>\n<p>注意这里的 M 覆盖主干权重与 VAE 解码的激活峰值，一旦引入 TP，每张卡上的 M 被切成 M/N，但通信缓冲区、all-reduce 的暂存区、以及反量化时的临时高精度 tile 都要从同一个 M 里扣。工程上常见的错误是按“权重总量除以 N”估卡数，结果在 VAE 解码段撞墙——解码激活峰值不随主干 TP 缩小，它只随解码段自己的切分缩小。</p>\n\n<h3 id=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-35\">三十五 · NVLink 5 与 NVSwitch：把 All-Reduce 的代价算清楚</h3>\n<p>B200/GB200 NVL72 这一档的机内互联是 NVLink 5 加 NVSwitch，72 个 GPU 处于同一 NVLink 域内，任意两卡之间是一跳，不存在跨机箱的层级跳数差异。这对 TP 的 all-reduce 是决定性的：TP 组只要落在同一 NVLink 域内，集合通信的拓扑就退化成近似全连接的交换结构，ring 还是 tree 的选择只影响算法效率，不影响可达带宽上限。TP 每层做两次 all-reduce（前向一次、反向不需要，但推理里注意力和 FFN 各一次），单次通信量为 batch × seq × hidden × dtype 字节数，通信时间近似：</p>\n<div class=\"formula\">$$T_{\\text{comm}} \\approx \\frac{2 \\cdot (N-1)}{N} \\cdot \\frac{S}{B_{\\text{nvlink}}} + L_{\\text{lat}}$$</div>\n<p>其中 S 是单次 all-reduce 的字节数，B 是有效带宽，L 是集合通信的固定延迟。N 越大，括号里的系数越接近 2，意味着 TP 度数的收益在通信侧是递减的：从 2 到 4 通信量涨得比计算下降慢，从 4 到 8 就开始打平。对扩散推理更不利的是，少步采样让“计算/通信比”天然偏低——LLM 解码阶段每步只算一个 token，尚且能靠大 batch 把 GEMM 做大；扩散的每一步是对整张潜变量图做一次完整的前向，单步计算量不小，但步数只有个位数，整个请求的生命周期里 all-reduce 的次数是“层数 × 步数”，层数动辄几十，步数个位数，乘起来仍是几十到几百次集合通信。每次通信的固定延迟 L 在 NVLink 域内是微秒级，几百次叠加就是毫秒级的固定开销，对单张图的端到端延迟是可观的份额。</p>\n<p>具体例子：一个 24 层 DiT 主干、8 步采样、TP=4 的配置，单请求要经历 24×8×2 ≈ 384 次 all-reduce。若每次固定延迟按微秒量级计，仅集合通信的固定部分就吃掉数百微秒到一毫秒量级，而单步去噪的计算在 B200 上被 tcgen05 压得很短。这就是“通信什么时候成为瓶颈”的第一个判据：当 TP 度数升高使单卡计算时间降到与集合通信延迟同量级时，继续加 TP 度数只会让延迟变差。此时正确动作是把 TP 度数收回到 2 或 4，用 DP 扩吞吐，而不是硬堆 TP。</p>\n\n<h3 id=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-36\">三十六 · All-to-All 在扩散推理里的缺席与 NIXL 的角色</h3>\n<p>All-to-All 是 MoE 的标配，也是 EP 的通信形态：token 按路由结果被打散到各专家所在卡，算完再散回。扩散主干不是 MoE，所以本方法的推理路径上不该出现 All-to-All；如果部署方把主干换成 MoE 化的 DiT，那么 All-to-All 的通信量随 batch × seq × top-k 增长，且是“非对称、非规整”的流量，对 NVSwitch 的冲击远大于 all-reduce 的规整流量。在没有 MoE 的前提下，把 All-to-All 当成瓶颈来优化是浪费工程预算——这是判断通信瓶颈的第二个判据：先确认拓扑里有没有 EP，没有就不要为 All-to-All 预留带宽。</p>\n<p>NIXL 的位置不同。它是面向推理的传输层，负责在节点间搬 KV cache、搬权重分片、搬潜变量与中间张量，典型场景是分离式预填/解码、多副本间的请求迁移、以及权重从存储侧加载到显存。对 MixDQ 这条管线，NIXL 最相关的用法是把量化后的低位宽权重分片按需传输到目标 GPU，以及在 DP 副本之间做请求重定向。传输的代价是显存带宽与链路带宽的乘积项：一次权重分片的传输时间 ≈ 分片字节数 / 链路有效带宽，而低位宽量化在这里是直接收益——4 bit 权重相对 16 bit 把传输字节数压到四分之一，NIXL 的搬运时间同比例下降。反过来说，如果部署把量化收益全用在“省显存”上而没用在“省传输”上，就等于放弃了 NIXL 侧的一半好处。工程判断：当权重加载时间占请求冷启动延迟的比例超过单步计算时间时，量化 + NIXL 的组合收益才真正显现；热路径上权重常驻，NIXL 只在副本扩缩容和故障迁移时出场。</p>\n\n<h3 id=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-37\">三十七 · 通信成为瓶颈的三个判据与量化带来的变量</h3>\n<p>把上面的分析收成可操作的判据。判据一，计算/通信比：单卡单步计算时间 T_comp 与单次集合通信时间 T_comm 的比值，若 T_comm / T_comp 超过约一成，TP 度数再加就是负收益。判据二，请求生命周期内的通信次数：层数 × 步数 × 2，这个数在少步场景下依然不小，固定延迟项不可忽略。判据三，显存预算 M 的挤占：通信缓冲区与反量化临时 tile 从同一个 M 里扣，TP 度数越高，每卡 M 越小，可用于批大小的余量越少，吞吐反而下降。</p>\n<p>MixDQ 的混合精度给这三条判据各加了一个变量。第一，低位宽权重让单卡计算时间 T_comp 缩短（访存受限的层尤其明显），于是 T_comm / T_comp 被动变大——量化本身会把系统推向通信瓶颈，这是容易被忽略的耦合效应：你把计算做快了，通信的相对占比就上升了。第二，权重与激活分别配置比特，意味着 all-reduce 的通信量取决于激活位宽而非权重位宽；若激活压到 8 bit 而权重压到 4 bit，all-reduce 的字节数按 8 bit 算，不能按 4 bit 估。第三，敏感层保留高比特，这些层的计算时间不缩短，它们在 TP 组里成为“慢层”，集合通信要等最慢的分片，负载不均衡会把 TP 的有效加速比拉低。</p>\n<table class=\"mini\"><thead><tr><th>判据</th><th>触发条件</th><th>量化后的变化</th><th>工程动作</th></tr></thead><tbody><tr><td>计算/通信比</td><td>T_comm / T_comp 超过一成</td><td>T_comp 因低位宽缩短，比值被动升高</td><td>TP 度数回调，改 DP 扩吞吐</td></tr><tr><td>通信次数</td><td>层数 × 步数 × 2 的固定延迟可感</td><td>步数不变，层数不变，次数不变</td><td>减少 TP 组规模，缩短单次延迟</td></tr><tr><td>显存挤占</td><td>每卡 M 被通信缓冲与临时 tile 吃掉</td><td>低位宽省出的显存被 TP 切分抵消</td><td>VAE 解码单独分组，不并入主干 TP</td></tr></tbody></table>\n<p>具体例子：同一台 GB200 NVL72 上跑两个副本，副本 A 用 TP=8、DP=1，副本 B 用 TP=4、DP=2。A 的单请求延迟更低但每卡显存余量小、批大小上不去；B 的 all-reduce 次数减半、每卡 M 更大，能合并 CFG 正负分支成一个批来摊薄权重读取。在少步采样下，B 往往在吞吐上胜出，因为延迟的绝对值已经被个位数步数压得很低，SLO 的余量足够吸收 TP 降低带来的单步变慢。这正是“通信什么时候成为瓶颈”的答案落点：不是通信绝对慢，而是量化把计算做快之后，通信的相对份额上升，此时并行的正确形态从“切得更细”转向“切得更少、副本更多”。</p>\n\n<h3 id=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-38\">三十八 · VAE 解码段的并行与显存峰值核算</h3>\n<p>VAE 解码器是这条管线上最容易被并行方案忽略的一段。它不参与主干的 TP 分组，原因是解码的激活峰值形态与主干不同：主干是规整的 token 序列，解码是空间分辨率逐级放大的卷积/上采样，激活峰值出现在最高分辨率的特征图上，且随 batch 线性增长。把解码并入主干 TP 会让主干的高比特敏感层与解码的低比特层共享同一个通信组，all-reduce 的同步点被解码的长尾拖住。正确做法是解码单独成组，按空间维度切分（把图像切成条带分给不同卡），组内通信量远小于主干的 all-reduce，因为条带之间只在边界处需要 halo 交换。</p>\n<p>显存核算上，量化节省的显存必须分成两份看：主干权重压缩省出的显存可以直接换成更大的批大小或合并 CFG 正负分支；解码激活峰值省出的显存取决于解码段自己的比特配置，与主干无关。若部署只压缩主干而把解码留在高比特，解码峰值仍可能触发溢出，此时 NIXL 侧的权重传输再快也无济于事——瓶颈不在通信，在显存。工程判断的顺序应当是：先按解码峰值定 batch 上限，再按主干权重与激活定 TP 度数，最后才看通信是否落在判据一的阈值内。这个顺序反了，就会出现“TP 调到 8、通信开销吃掉收益、解码仍然 OOM”的三重浪费。</p>\n\n<h3 id=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-39\">三十九 · 切分拓扑与量化配置的耦合边界</h3>\n<p>MixDQ 的比特分配是模块粒度的静态配置，而并行切分是部署期的动态拓扑，两者耦合处正是这套方案最容易失效的地方。TP 把主干每层的权重矩阵按列或行切开，各 rank 持有的是同一层不同分片，但混合精度配置是按层名索引的——一旦层被切分，反量化必须在每个 rank 的分片上独立执行，再经 All-Reduce 汇总部分和。代价在于：反量化后的高精度激活在 All-Reduce 前必须保持统一 dtype，否则 NCCL 归约会触发隐式类型转换，把低比特节省的带宽又还回去。EP 场景下 MoE 式主干更麻烦，token 经 All-to-All 分发后落在不同 rank 上的专家可能持有不同位宽，接收端需按来源 rank 的配置做条件反量化，这条分支在 kernel 内引入发散。PP 则把敏感层与非敏感层分到不同 stage，stage 间只传激活，量化误差不跨 stage 累积，但流水气泡会吃掉量化换来的批吞吐增益。用 $\\tau_{\\text{comm}} = \\frac{S \\cdot (N-1)}{B_{\\text{nvl}}}$ 粗估单次 All-Reduce 时延，其中 $S$ 为反量化后激活字节数、$N$ 为 TP 度、$B_{\\text{nvl}}$ 为 NVLink 5 有效带宽；当 $S$ 因保留高位宽而膨胀时，通信项迅速压过计算项。</p>\n<p>通信成为瓶颈的判据不在拓扑本身，而在“量化节省的显存是否被兑换成了通信量”。MixDQ 把 VAE 解码峰值纳入预算 $M$，但预算只约束显存、不约束带宽：把主干压到极低比特后，单卡可以承载更大批，CFG 正负分支合并后批维翻倍，此时 TP 组内每步需归约的激活规模随批线性增长，而权重读取因量化而下降——访存与通信的比值被反转。具体例子：主干某敏感层保留较高位宽以抑制个位数步下的单步误差，该层在 TP=8 时每 rank 的反量化激活为 $S$，每步一次 All-Reduce，步数虽只有个位数但批内并发高，通信时延与单步计算时延同量级，流水线从计算受限滑向通信受限。此时正确做法不是继续压比特，而是降低 TP 度、改用 DP 复制权重并以更大批摊薄，或把该层留在单卡内做 2-SM MMA 避免跨卡归约。</p>\n<table class=\"mini\"><thead><tr><th>切分方式</th><th>量化配置的作用点</th><th>主要系统代价</th><th>失效条件</th></tr></thead><tbody><tr><td>TP</td><td>逐 rank 分片反量化后 All-Reduce</td><td>归约带宽随批与位宽膨胀</td><td>敏感层高位宽 + 大批 + 高 TP 度</td></tr><tr><td>EP</td><td>按来源 rank 条件反量化</td><td>All-to-All 时延与 kernel 发散</td><td>专家位宽异构、token 分布倾斜</td></tr><tr><td>PP</td><td>stage 内独立配置，跨 stage 传激活</td><td>流水气泡抵消批增益</td><td>stage 数多、单 stage 计算量小</td></tr><tr><td>DP</td><td>权重复制，无归约</td><td>显存复制开销</td><td>单卡显存不足以容纳复制权重</td></tr></tbody></table>\n<p>NIXL 在这条链路上的角色是跨节点传输潜变量与条件嵌入，而非参与 TP 归约；当分离式预填/解码把 VAE 解码放到独立节点时，潜变量经 NIXL 搬运的字节数远小于主干激活，通信不构成瓶颈，但解码节点的显存峰值必须单独按 $M$ 核算，否则主干省下的显存被解码端溢出抵消。工程判断落在一条硬约束上：量化配置的搜索目标应加入通信项，把 $\\lambda$ 的折中从“感知 vs 重建”扩展为“感知 vs 重建 vs 归约字节”，并在拓扑确定后再冻结比特表——先定 TP/EP 度、再跑校准搜索，而不是先搜比特再套拓扑。材料未给出 λ 取值与 Blackwell 档位实测，因此这条约束只能以定性方式进入部署检查清单：单步延迟中通信占比超过计算占比时，回退敏感层位宽或降低并行度，优先保住少步采样下单步误差不被放大。</p>\n<h3 id=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-40\">四十 · 精度塌陷：从“指标正常”到“图崩了”的断层</h3>\n<p>MixDQ 的失败模式里，最隐蔽的一类是精度塌陷——服务端监控的吞吐、显存、单步延迟全部在预算内，但输出图像出现结构性崩坏：语义漂移、局部色块、文字提示词对应关系丢失。根因在于度量解耦框架把感知度量与重建度量拆成两项，而线上监控通常只挂了其中一项（多为重建类代理指标），另一项塌陷时无人察觉。少步采样是放大器：个位数步数下，单步量化误差不被后续多步平均稀释，敏感层（文本编码器条件嵌入、主干注意力投影）一旦被压到过低比特，误差直接写进最终潜变量。</p>\n<p>诊断机制要落到逐层敏感度而非全局比特。做法是对每一层做一次“单层回退探针”：固定其余层配置，仅把第 <em>l</em> 层权重与激活抬高一档比特，重跑同一批提示词，比较感知度量差分。若差分超过阈值，该层标记为敏感层并进入回退候选集。形式化地，把配置搜索的目标写成</p>\n<div class=\"formula\">$$\\Delta_l = \\mathcal{L}_{\\text{percept}}(\\hat{x}(b_l^{+})) - \\mathcal{L}_{\\text{percept}}(\\hat{x}(b_l)), \\quad \\text{回退若} \\; \\Delta_l &gt; \\tau$$</div>\n<p>代价是探针本身要跑完整采样管线：每层一次探针意味着 N 层 × 单次少步采样，显存峰值与正常推理相同，但吞吐为零——这是纯离线诊断开销，必须放在发布前的校准窗口而非线上。工程判断：探针集只需覆盖提示词长度分布的两端（极短与极长），因为文本编码器开销随长度抬升，长提示词会同时抬高条件嵌入阶段的显存与量化误差暴露面。</p>\n\n<h3 id=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-41\">四十一 · OOM：预算约束漏掉 VAE 解码峰值</h3>\n<p>第二类失败是显存溢出，且几乎总发生在 VAE 解码阶段而非主干去噪阶段。MixDQ 的预算约束写作 <em>Σ mem(b_l) ≤ M</em>，但材料明确指出该预算须同时覆盖主干权重与 VAE 解码的激活峰值；只压缩主干权重的团队会在解码时撞墙——主干省下的显存被解码激活一口吃掉，甚至因为量化节省后批大小被调大，解码峰值随批线性上升而率先越界。这是“优化了错误的对象”的典型：权重体积是静态的、可预算的，解码激活是动态的、随批与分辨率变化的。</p>\n<p>定位手段是把显存核算拆成两本账：主干账（权重 + 逐层反量化临时缓冲 + 注意力中间激活，按步复用并及时释放）与解码账（VAE 输入潜变量 + 解码器逐层激活峰值）。监控上对两本账分别打点，而不是只看进程级显存总量——进程级数字会被缓存分配器的碎片掩盖，出现“总量没超但分配失败”的假阴性。回滚策略按账本分治：主干账超限时回退敏感层比特；解码账超限时优先降批大小或对 VAE 单独配置更高压缩档，而不是动主干——因为主干比特回退会同时牺牲吞吐，而解码阶段对量化误差的容忍度与主干不同，材料明确要求 VAE 解码单独评估。</p>\n<p>具体例子：CFG 正负分支合并为一个批以摊薄权重读取开销，这是吞吐优化；但合并后批大小翻倍，解码账的激活峰值同步翻倍。若预算 M 只按单分支核算，合并批在解码阶段直接 OOM。正确做法是把 CFG 合并后的批规模代入解码账重算 M，再反推主干可用的比特预算。</p>\n\n<h3 id=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-42\">四十二 · 批抖动：动态批与少步采样的相位冲突</h3>\n<p>批抖动指吞吐与延迟随批组成剧烈波动，表现为同一 SLO 下 P99 延迟时好时坏。机制根源在于少步扩散的单请求计算量小、解码占比高，批内请求的提示词长度与采样步数若不一致，批的实际执行时间由最长者决定，短请求被“搭便车”拖尾。量化把这一效应放大：低位宽权重加载后逐层反量化，反量化开销与访存节省的权衡材料未给出实测数字，但可以确定反量化是逐层的、与批大小弱相关的固定开销，批越小摊薄越差——小批时反量化占比上升，大批时解码激活占比上升，中间存在一个抖动区间。</p>\n<p>监控上不要只看平均批大小，要打“批组成直方图”：批内提示词长度的方差、批内步数分布、以及批实际执行时间与批内最长请求单独执行时间的比值。后者接近 1 说明批内同质，显著大于 1 说明存在拖尾。调度侧的回滚不是降比特，而是收紧批上限或引入按长度分桶——把长提示词请求单独成批，避免它们污染短请求批的尾延迟。这与前文调度部分讲的连续批处理是同一套机制的不同侧面：连续批处理解决的是批的填充效率，批抖动解决的是批的同质性。</p>\n\n<h3 id=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-43\">四十三 · 尾延迟：解码阶段是 P99 的主贡献者</h3>\n<p>尾延迟的定位要区分两段：去噪段与解码段。少步采样把去噪段压到个位数步，单步延迟低且方差小；VAE 解码是一次性的、激活峰值高的、对批大小敏感的操作，P99 几乎由解码段决定。量化在此处的陷阱是：主干比特压得越低，去噪段越快，请求越早涌入解码段，解码段的排队与峰值显存压力反而上升——吞吐提升了，尾延迟恶化了。这是“局部最优导致全局次优”的服务化典型。</p>\n<p>诊断用分段计时打点：记录每个请求的入队时刻、去噪完成时刻、解码完成时刻，分别算两段的 P50/P99。若解码段 P99 显著高于 P50 且与批大小正相关，判定为解码段容量不足，回滚动作是限制并发批数或对 VAE 单独降精度档（在预算约束内），而不是继续压主干。容量规划的判断落在解码账上：解码段的显存峰值与批大小近似线性，SLO 给定的 P99 预算反推出解码批上限，主干比特配置在这个上限下再优化——顺序不能反。</p>\n\n<h3 id=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-44\">四十四 · 静默降级：没有报错的失败最贵</h3>\n<p>静默降级指系统在无异常、无告警的情况下输出质量缓慢劣化：某次配置搜索把 λ 调偏，感知度量与重建度量此消彼长，重建指标好看、感知质量下滑；或某层敏感度评估过期（换了提示词分布），低位宽敏感层未被回退。这类失败不触发 OOM、不抬高延迟，只能靠质量监控捕获。监控项必须包含与线上提示词同分布的周期性质量抽检：固定一组提示词，按固定间隔重跑并计算感知度量，与基线配置的输出做差分。差分超阈值即触发配置回滚到上一版已知良好配置。</p>\n<p>回滚机制要版本化：每次比特配置变更（λ、模块粒度分配、VAE 是否单独配置）都作为不可变配置版本登记，附带当时的抽检基线。回滚是配置级的原子切换，不是逐层热改——逐层热改会让中间状态不可复现，诊断时无法归因。工程判断：把度量解耦的两项权重 λ 当成需要按目标 SLO 调参的运行参数而非一次性超参，因为感知与重建的折中随负载分布漂移；材料未给出 λ 的具体取值，落地时以抽检差分最小化为准，而非追求单项指标最优。</p>\n<p>最后落在具体机制上：静默降级的根因往往是把度量解耦当成免费收益。两项度量解耦后分别指导比特分配，但解耦不等于独立——感知度量对敏感层比特的梯度远大于重建度量，λ 选择不当会让搜索把预算全押在重建项上，敏感层被压到低位宽而重建指标仍达标。诊断这类失败的唯一可靠信号是端到端感知抽检，而不是任何单层数值指标；回滚的最小单元是配置版本，不是单层比特。</p>\n\n<h3 id=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-45\">四十五 · 量化配置的失效边界与线上诊断闭环</h3>\n<p>MixDQ 的比特分配是在给定显存预算下求解感知度量与重建度量的加权和，这个优化式在离线校准阶段成立，但在线上服务里它会沿三个方向失效。其一是 λ 的错配：当 λ 偏大时，搜索会为压低重建误差而给不敏感模块保留多余位宽，显存预算被浪费、批大小上不去；当 λ 偏小时，感知度量被牺牲，图像出现结构性伪影，而重建误差指标看起来仍然“正常”，形成典型的静默降级。其二是预算约束 M 的核算口径：约束式 <span class=\"formula\">$$\\sum_l \\text{mem}(b_l) \\le M$$</span> 若只统计主干权重，VAE 解码阶段的激活峰值就会在解码瞬间把显存顶穿，表现为“采样全部成功、解码阶段 OOM”的错位故障。其三是少步采样对单步误差的放大：个位数步数下误差不被后续多步平均稀释，任何一层被压到过低比特都会直接反映到像素，因此逐层敏感度评估缺失时，全局统一比特的回退策略必然不够。</p>\n<p>诊断要按模块分段埋点，而不是只看端到端指标。建议的最小监控面包括：文本编码器输出嵌入的数值偏差（与高精度参考的余弦距离）、主干每步去噪后潜变量的重建残差、VAE 解码前的激活峰值显存、以及单请求的分段耗时（条件嵌入 / 采样 / 解码）。批抖动与尾延迟通常同源：CFG 正负分支合并为一个批后，批内提示词长度分布拉长，文本编码器阶段成为长尾；解码阶段激活峰值随批大小线性抬升，一旦越过预算，调度器被迫降批，吞吐出现阶跃式下跌。定位手段是把批大小与分段显存画成二维表，找出“解码峰值先撞墙”还是“采样步延迟先撞墙”，二者对应的回滚动作不同。</p>\n<table class=\"mini\"><thead><tr><th>症状</th><th>最可能根因</th><th>定位信号</th><th>回滚动作</th></tr></thead><tbody><tr><td>图像结构崩坏但重建指标正常</td><td>λ 偏小，感知度量被牺牲</td><td>嵌入余弦距离正常、潜变量残差偏大</td><td>提高敏感层位宽，重跑校准搜索</td></tr><tr><td>采样完成后 OOM</td><td>预算未覆盖 VAE 解码激活峰值</td><td>解码前显存曲线陡升</td><td>单独抬高 VAE 位宽或限制批大小</td></tr><tr><td>吞吐阶跃下跌、尾延迟抬升</td><td>批内长度分布拉长、解码峰值撞墙</td><td>分段耗时与显存二维表</td><td>按 SLO 设批上限，拆分 CFG 批</td></tr></tbody></table>\n<p>回滚必须做到模块粒度可逆：把文本编码器、主干、VAE 三段的位宽配置做成独立可切换的档位，线上出现质量告警时只回退告警段，而不是整条管线退回统一高精度——后者会让显存瞬间回到压缩前水平，批大小被迫腰斩，吞吐代价远大于局部回退。工程判断上，把“解码峰值显存”与“感知度量漂移”设为两个独立的一级告警项，前者触发批调度降级，后者触发比特档位回退；两者共用同一套校准产物，才能在 B200/GB200 档位上把量化收益稳定兑现，而不是在校准集上好看、在长尾提示词上塌陷。</p>\n<h3 id=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-46\">四十六 · 口径的第一层：模型与负载形态决定了哪些数字才有意义</h3>\n<p>读 MixDQ 这类量化工作的性能数字，第一步不是看吞吐涨了多少，而是确认被测对象处在什么负载形态上。少步文本到图像的推理管线由三段构成：文本编码器把提示词压成条件嵌入，主干（UNet 或 DiT）在个位数步内迭代去噪，VAE 解码把潜变量还原成像素。这三段的时间占比与显存占比完全不同——主干是计算密集段，VAE 解码是激活峰值段，文本编码器则随提示词长度线性伸缩。因此任何“端到端加速比”都必须标明它是否包含 VAE 解码、是否包含文本编码，否则两个数字根本不在同一口径上。</p>\n<p>更关键的是负载形态。单请求单图像的离线批处理与在线服务是两种完全不同的测量对象：前者可以用大 batch 把权重读取摊薄到极致，后者受队列延迟约束，batch 上限由 SLO 反推。MixDQ 的材料明确把 CFG 的正负分支合并为一个批来摊薄权重读取开销，这一操作在离线吞吐口径下收益显著，在低延迟口径下却可能因为批变大而抬高单请求尾延迟。所以看到“吞吐提升”时，先问：CFG 是否合并、batch 是静态还是动态、并发请求数是多少。</p>\n<p>度量本身也要对齐。少步采样把步数压到个位数，单请求的计算量下降，但每步的量化误差不再被后续多步平均稀释——这是 MixDQ 强调敏感层保真的机制根源。于是质量指标（感知度量）与性能指标（延迟、吞吐、显存）之间存在强耦合：把主干压到更低比特能省显存、提吞吐，但感知度量会退化。任何只报性能不报质量的数字，在少步场景下都是不完整的口径。</p>\n<div class=\"formula\">$$\\text{端到端延迟} = T_{\\text{text}} + \\sum_{s=1}^{S} T_{\\text{denoise}}^{(s)} + T_{\\text{vae}},\\quad S \\in \\{1,\\dots,9\\}$$</div>\n<p>这条分解式说明为什么“单步延迟”不能直接乘以步数得到端到端：文本编码器与 VAE 解码是固定开销，在 S 很小时占比反而上升。举例来说，若某配置把主干单步延迟压到很低，但 VAE 解码的激活峰值迫使 batch 只能取 1，那么端到端吞吐仍被解码段锁死——这正是 MixDQ 把 VAE 解码显存峰值单独纳入预算约束 $M$ 的工程理由。</p>\n\n<h3 id=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-47\">四十七 · 硬件档位：材料没给，就必须把档位当成口径变量而非常数</h3>\n<p>MixDQ 的材料明确未给出部署硬件档位、并行拓扑与 B200/GB200 上的实测数据。这不是可以含糊过去的小事，而是口径问题的核心：同一份混合精度配置，在 SM100 与 SM103 上的实际收益取决于低精度算子支持程度、显存带宽与 TMEM 的可用性。若反量化在 Tensor Core 路径上无法融合，逐层反量化引入的额外指令与访存会吃掉压缩带来的带宽节省；材料同样未给出反量化开销与访存节省的实测权衡数字。因此把论文的“显存压缩比”直接换算成 Blackwell 上的吞吐提升，是把两个不同口径混为一谈。</p>\n<p>正确的读法是分层：第一层是算法口径，即比特分配在给定显存预算下对感知度量的影响，这部分与硬件无关，可跨档位比较；第二层是算子口径，即低位宽权重加载后反量化能否被 tcgen05 路径高效消费，这部分强依赖档位与内核实现；第三层是系统口径，即显存节省能否转化为更大 batch 或更高并发，这部分依赖调度器与显存峰值监控。三层中只有第一层是论文能直接支撑的，后两层在材料缺失时必须标为待实测。</p>\n<table class=\"mini\"><thead><tr><th>口径层</th><th>可比较性</th><th>材料支撑</th><th>工程动作</th></tr></thead><tbody><tr><td>算法层（比特分配 vs 感知度量）</td><td>跨档位可比</td><td>有，框架层面</td><td>按模块敏感度复核配置</td></tr><tr><td>算子层（反量化融合效率）</td><td>仅同档位可比</td><td>无实测</td><td>在目标档位跑微基准</td></tr><tr><td>系统层（显存→batch→吞吐）</td><td>仅同调度策略可比</td><td>无实测</td><td>按 SLO 定 batch 上限后实测</td></tr></tbody></table>\n<p>具体例子：若在 B200 上测得某混合精度配置把主干权重显存压到原来的几分之一，但 VAE 解码的激活峰值不变，则系统层收益只体现在“能开更大 batch”这一条路径上；若调度器仍按原 batch 上限运行，显存节省就完全无法转化为吞吐。这就是为什么档位与调度必须一起报，单报显存压缩比没有系统意义。</p>\n\n<h3 id=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-48\">四十八 · batch 与并发：CFG 合并是口径分水岭</h3>\n<p>MixDQ 的服务端做法是把 CFG 的正负分支合并为一个批，用一次权重读取同时算两个分支。这在口径上制造了一个分水岭：合并后的“有效 batch”是请求数的两倍，权重读取开销被摊薄，但单次前向的激活显存也翻倍。于是同一份量化配置，在合并口径下显存预算更容易触顶，在非合并口径下则显得宽裕。比较两个系统的吞吐时，必须确认双方是否都做了 CFG 合并，否则数字不可比。</p>\n<p>并发维度同理。在线服务的并发请求数决定队列深度，而扩散推理的单请求延迟由采样步数与解码时间主导。量化节省的显存可以用于提高并发批数，但并发提高会拉长尾延迟；材料未给出具体并发档位与 SLO 设定，因此任何“并发提升 N 倍”的说法都缺少口径锚点。工程上应把并发当作受 SLO 约束的因变量：先定 TTFT 与单请求完成时间的上限，再反推可用的 batch 与并发，最后看量化节省的显存是否足以支撑该 batch。</p>\n<div class=\"formula\">$$\\text{吞吐}_{\\text{有效}} = \\frac{B_{\\text{req}} \\cdot \\mathbb{1}[\\text{peakMem}(B_{\\text{req}}, \\{b_l\\}) \\le M]}{T_{\\text{req}}(B_{\\text{req}})},\\quad B_{\\text{req}} = 2 \\cdot B_{\\text{cfg-merged}}$$</div>\n<p>这条式子把 CFG 合并显式写进吞吐定义：$B_{\\text{req}}$ 是请求数，合并后前向批是它的两倍，显存约束作用在合并批上。举例：若某配置在非合并口径下能开 batch 8，合并后前向批变成 16，激活峰值可能越过 $M$，此时要么回退敏感层比特、要么降低请求并发——两种动作对应完全不同的吞吐数字，报告时必须写明选了哪条。</p>\n\n<h3 id=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-49\">四十九 · 指标族：TTFT/TPOT 在扩散推理里要重新定义</h3>\n<p>TTFT（首 token 时间）与 TPOT（每 token 时间）是从自回归推理借来的指标，直接套到扩散上会失真。扩散没有 token 流，只有步流：首步去噪完成的时间更接近“首帧可用”的语义，而后续每步的时间才是 TPOT 的类比物。MixDQ 的材料未给出这些指标的具体测量方式，因此读数字时要确认：TTFT 是指文本编码完成、首步去噪完成，还是首张图像返回？三者差异巨大，尤其当 VAE 解码占端到端时间不小的时候。</p>\n<p>更贴合扩散服务的指标族应包括：单步去噪延迟（区分主干前向与反量化开销）、VAE 解码延迟与激活峰值、端到端单请求完成时间、以及给定 SLO 下的有效吞吐。显存指标要分权重显存与激活峰值两项报，因为 MixDQ 的预算约束同时覆盖主干权重与解码激活；只报权重压缩比会掩盖解码段的峰值风险。功耗指标材料完全未涉及，在 Blackwell 高功耗档位上，量化降低的访存量是否转化为功耗节省取决于内存子系统占比，不能默认成立。</p>\n<ul><li>延迟族：文本编码、单步去噪、VAE 解码、端到端，四段分开报。</li><li>吞吐族：注明 CFG 是否合并、batch 静态或动态、并发档位。</li><li>显存族：权重体积与激活峰值分开，VAE 解码单列。</li><li>质量族：感知度量与重建度量分开报，对应 MixDQ 的解耦框架。</li></ul>\n<p>具体例子：一个只报“端到端延迟降低”的结果，若未拆分 VAE 段，就无法判断收益来自主干量化还是解码优化；而 MixDQ 的机制恰恰是把解码峰值纳入预算，因此拆分报告才能验证其主张是否在系统层兑现。</p>\n\n<h3 id=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-50\">五十 · 哪些提升不可比：四类典型陷阱</h3>\n<p>第一类，质量口径不同。MixDQ 的目标函数是感知度量与重建度量的加权和，$\\lambda$ 控制折中，材料未给出 $\\lambda$ 取值。两个系统若用不同的 $\\lambda$ 或不同的感知度量实现，其“同等质量下显存更低”的结论不可直接比较。第二类，基线不同。材料明确基线是统一精度量化方案但未给出名称与数字，因此“相对统一比特的提升”只能在同基线同评测协议下读，跨论文拼接数字是无效比较。</p>\n<p>第三类，是否含 VAE。只压缩主干权重的方案与把解码峰值纳入预算的方案，在端到端显存口径上不在同一层；前者可能在解码阶段仍触发显存溢出，后者则把预算约束写进了搜索。第四类，步数不同。少步采样的步数是口径的一部分：个位数步数下误差不被稀释，同一比特配置在更多步的模型上表现会不同，跨步数比较量化收益没有意义。</p>\n<table class=\"mini\"><thead><tr><th>陷阱</th><th>表现</th><th>读法</th></tr></thead><tbody><tr><td>质量口径</td><td>λ 与度量实现不同</td><td>只在同 λ 同度量下比</td></tr><tr><td>基线口径</td><td>统一比特方案未具名</td><td>不跨论文拼接数字</td></tr><tr><td>VAE 口径</td><td>是否含解码峰值</td><td>显存分权重与激活报</td></tr><tr><td>步数口径</td><td>个位数步 vs 多步</td><td>同模型同步数才可比</td></tr></tbody></table>\n<p>工程判断上，遇到一个“显存降低、吞吐提升”的数字，先做三问：质量度量与 λ 是什么、基线是否同协议、VAE 解码是否在口径内。三问有一问不满足，该数字就只能作为方向性证据，不能作为容量规划的输入。MixDQ 的材料未给出 FID、CLIP 分数、显存与吞吐的具体数值，因此其主张应被读作“框架可行”，而非“已兑现的容量收益”。</p>\n\n<h3 id=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-51\">五十一 · 把口径写进容量规划：从数字到可执行判断</h3>\n<p>容量规划需要的是可复现的口径，而不是论文里的单一数字。做法是把 MixDQ 的预算约束 $M$ 拆成三项：主干权重显存、主干激活峰值、VAE 解码激活峰值，并按目标档位分别实测。搜索得到的混合精度配置 $\\{b_l\\}$ 只有在三项之和不超过 $M$ 且感知度量满足阈值时才可上线；上线后监控单步延迟、显存峰值、batch 与质量指标，超预算时回退敏感层比特——这是材料给出的监控项，也是口径落地的闭环。</p>\n<p>具体机制上，逐层反量化的开销必须被单独测量：低位宽权重加载节省的是访存带宽，但反量化指令若不能与矩阵乘融合，就会把节省吐回去。在 Blackwell 上这意味着要确认反量化是否走在 tcgen05 的消费路径上，材料未给出该对照，因此这一步只能靠目标档位微基准补齐。工程判断是：在补齐之前，把量化收益记为“显存侧确定、吞吐侧待定”，容量规划按显存侧收益保守估算 batch 上限，吞吐按实测回填。</p>\n<div class=\"formula\">$$M \\ge \\text{mem}_{\\text{w}}(\\{b_l\\}) + \\text{peak}_{\\text{act}}^{\\text{backbone}} + \\text{peak}_{\\text{act}}^{\\text{vae}}$$</div>\n<p>这条约束是整篇论文口径的核心：它把 VAE 解码从“事后问题”变成“搜索前置条件”。读任何 MixDQ 相关的性能数字时，只要看到报告方没有把这三项分开，就可以判定该数字不足以支撑容量决策。最后落在机制上：比特分配是离线搜索的产物，而口径是线上监控的产物，两者必须在同一个 $M$ 下对齐，否则量化节省的显存只存在于论文表格里，不会出现在服务端的 batch 上限里。</p>\n<h3 id=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-52\">五十二 · 迁移的第一道关：误差稀释假设是否成立</h3>\n<p>MixDQ 的比特分配逻辑建立在一条明确的机制前提上：少步采样使单步量化误差不被后续多步平均稀释，因此敏感层必须保留较高位宽。这条前提决定了整套配置能否平移。迁到别的模型时，第一件要核对的不是模型结构，而是采样步数分布——如果目标模型仍是几十步的常规 DDIM/DPMSolver 采样，误差在时间轴上被反复平均，敏感层的边际收益会显著下降，此时把预算继续堆在文本编码器与主干前几层，性价比不如把预算让给 VAE 或干脆整体降一档位宽。反过来，迁到步数更极端的蒸馏模型（个位数甚至 1–2 步），误差稀释几乎不存在，度量解耦中的感知项权重必须上调，否则重建度量会把比特推向数值保真而非视觉保真，出现“数值更准但图更差”的倒挂。工程判断很直接：先测目标模型在目标步数下的单步误差敏感度曲线，再决定是否沿用 MixDQ 的模块划分；步数分布不匹配时，配置框架可迁移，具体比特表不可迁移。</p>\n<div class=\"formula\">$$\\mathcal{L}_{\\text{total}}=\\mathcal{L}_{\\text{percept}}(\\hat{x}(\\{b_l\\}))+\\lambda\\,\\mathcal{L}_{\\text{recon}}(\\{b_l\\}),\\quad \\sum_l \\text{mem}(b_l)\\le M$$</div>\n<p>代价侧要盯住的是搜索成本而非推理成本。按模块粒度搜索意味着配置空间随模块数组合增长，迁到一个模块更多的 DiT（层数、块数都多于 UNet）时，朴素网格搜索的校准开销会线性甚至组合膨胀；实际落地通常退化为逐模块贪心加局部回退，用一次前向的敏感度排序代替全局搜索。这一步的显存代价是校准期需要同时驻留高位宽参考模型与低位宽候选，B200 单卡 192GB 级别尚可容纳中等规模 DiT，但 GB200 NVL72 机柜内做多模型并行校准时，必须把校准批次压到很小以免挤占服务实例。</p>\n\n<h3 id=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-53\">五十三 · 模块边界重划：文本编码器、主干、VAE 的容忍度不可照搬</h3>\n<p>MixDQ 把管线切成文本编码器、主干、VAE 三段并分别配比特，这个切法在 T2I 上成立，是因为三段的误差传播路径不同：文本编码器的误差进入条件嵌入后被主干反复消费，VAE 的误差直接落在像素域且伴随解码激活峰值。迁到别的领域时，这个三段边界往往要重划。视频扩散模型多出时间维，主干内的时序注意力层对量化误差的容忍度低于空间注意力层，需要把“主干”再拆成空间块与时序块两组比特；而 6Bit-Diffusion 一类工作已经指出视频场景下推理期混合精度的粒度要更细，MixDQ 的模块级划分在这里只能作为上位框架，具体比特表要按时间层重排。迁到 DiT 类 T2I 时，文本编码器常被换成更大的 T5 或双编码器结构，条件嵌入维度上升，保留高比特的显存代价随之变大，此时更合理的做法是把文本编码器整体放到 CPU 或单独低并发实例上，而不是在主 GPU 上为它留高位宽。</p>\n<table class=\"mini\"><thead><tr><th>迁移目标</th><th>需改动的配置维度</th><th>主要代价</th></tr></thead><tbody><tr><td>常规多步 T2I</td><td>感知项权重下调，敏感层回退阈值放宽</td><td>搜索收益变薄，校准开销占比上升</td></tr><tr><td>视频扩散</td><td>主干拆空间/时序两组比特</td><td>时序层高位宽抬高权重显存与读取带宽</td></tr><tr><td>DiT + 大文本编码器</td><td>文本编码器外置或独立实例</td><td>跨设备条件嵌入传输延迟</td></tr><tr><td>VAE 高分辨率解码</td><td>解码激活峰值单独设预算上限</td><td>解码阶段显存峰值可能反超主干</td></tr></tbody></table>\n<p>VAE 这一段最容易被低估。MixDQ 明确把解码激活峰值纳入预算约束 M，而不是只优化主干权重体积；迁到高分辨率或视频解码时，解码激活随分辨率与帧数增长，可能成为整个管线真正的显存瓶颈。此时即便主干压到极低位宽，解码仍会触发 OOM，量化节省的显存无法转化为批大小。工程上应把 VAE 解码的峰值显存作为硬约束先算，再倒推主干可用预算，而不是反过来。</p>\n\n<h3 id=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-54\">五十四 · 硬件档位：反量化开销与原生低精度格式的错位</h3>\n<p>MixDQ 的推理形态是低位宽权重加载、逐层反量化后参与矩阵乘与注意力计算。这套形态在 Blackwell 上会遇到一个结构性错位：SM100/SM103 的原生低精度路径是 NVFP4/FP8 经 tcgen05 走 TMEM 的 2-SM MMA，硬件期望的是低精度直接进乘加单元，而不是先反量化回 BF16/FP16 再算。逐层反量化意味着权重读取省了，但反量化指令与寄存器压力增加，且低精度算力没有被真正用上——吞吐收益主要来自访存而非算力。迁到 Blackwell 时，正确的做法是把 MixDQ 的比特分配结果映射到硬件支持的档位集合（NVFP4、FP8、BF16），而不是任意位宽；非标准位宽（如 6 bit、5 bit）在 Blackwell 上没有原生 MMA 支持，只能走反量化或查表路径，其收益要按“访存节省减去反量化开销”重新核算，材料未给出该权衡的实测数字，因此必须以目标档位实测为准。</p>\n<p>规模上限由此浮现。单卡内，MixDQ 的收益上限由权重体积与解码峰值中较大者决定；一旦权重压到接近下限，收益就封顶在解码侧。跨卡时，混合精度配置与并行切分耦合：张量并行要求各 rank 上同一层的比特一致，否则集合通信前后的数值路径不对称；流水并行则让不同 stage 的显存预算独立核算，MixDQ 的全局预算约束 M 需要改成按 stage 的分段约束。GB200 NVL72 机柜内 NVLink 5 域很大，但把混合精度配置跨 72 卡统一搜索的校准成本不可忽略，实际更可能是按 stage 分组配置、组内统一比特。</p>\n\n<h3 id=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-55\">五十五 · 哪些场景不该用这套方案</h3>\n<ul>\n<li>步数未被压缩的常规采样管线：误差稀释充分，模块级混合精度的边际收益低于统一 FP8 的工程简洁性，维护多套比特表的复杂度不划算。</li>\n<li>对数值重建极端敏感的场合（如需要潜变量可逆还原、或下游有精确数值依赖）：感知度量与重建度量的解耦在这里失效，感知项权重再调也无法保证重建精度，应改用统一高位宽或只压非关键模块。</li>\n<li>极低位宽（2 bit 量级）：材料明确指出极端低位宽的失效边界缺少定量刻画，少步采样下单步误差直接反映到输出，2 bit 下敏感层回退不足会直接崩坏图像，没有逐层敏感度评估就不应尝试。</li>\n<li>VAE 解码占主导的高分辨率/视频服务：主干压缩带来的显存节省无法转化为吞吐，瓶颈在解码激活，应先解解码侧的显存问题（分块解码、潜空间压缩等），量化只是次要手段。</li>\n<li>缺少低精度算子支持的目标后端：若目标硬件对非标准位宽只有软件模拟路径，反量化开销可能吞掉访存收益，此时应优先选硬件原生格式而非追求更低位宽。</li>\n</ul>\n<p>这些边界的共同点是：MixDQ 的贡献是配置框架，不是一套放之四海皆准的比特表。框架的可迁移部分是两个度量解耦加显存预算约束；不可迁移部分是具体模块划分、λ 取值与比特档位。判断一个迁移是否值得做，只需回答三个问题：目标模型的步数是否足够少到误差不被稀释、解码峰值是否已被单独约束、目标硬件是否有对应的低精度算子路径。三者任一不成立，收益就会落在框架之外。</p>\n\n<h3 id=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-56\">五十六 · 规模上限的工程判断</h3>\n<p>把 MixDQ 放到 Blackwell 服务化的容量规划里，它的定位是“在步数已被蒸馏压缩的前提下，进一步把权重与激活显存压下来以换取批大小”。这个定位决定了它的规模上限不在单请求延迟，而在批吞吐的拐点：量化节省的显存用于合并 CFG 正负分支或提高并发批数，批越大，权重读取被摊薄得越充分，单位请求的显存成本越低；但批增大后激活显存线性上升，解码峰值随批同步抬高，最终仍会撞上解码侧的天花板。容量规划时应把预算 M 拆成权重预算与解码激活预算两段，按目标 SLO 的批上限反推可接受的比特档位，而不是先定比特再算批。</p>\n<div class=\"formula\">$$\\text{batch}_{\\max}\\approx\\frac{M_{\\text{free}}-M_{\\text{weight}}(\\{b_l\\})}{M_{\\text{act,decode}}+M_{\\text{act,denoise}}}$$</div>\n<p>这条式子里的每一项都对应一个可观测的监控量：权重显存由比特表决定，去噪激活随步数与批线性增长，解码激活随分辨率与批增长。工程判断落在最后一步——当解码激活项开始主导分母时，继续压低主干比特已不能提高 batch_max，此时应停止在主干上追加压缩，把工程投入转向解码侧的分块与潜空间优化。这也是 MixDQ 迁移到 Blackwell 时最实际的边界：它能帮你把权重项压到很小，但压不动解码项；规模上限由解码项与硬件低精度算子路径共同决定，而不是由比特表的激进程度决定。</p>\n\n<h3 id=\"paper-mixdq-memory-efficient-few-step-text-2024-sec-57\">五十七 · 迁移边界：度量解耦配置在哪些管线上失效</h3>\n<p>这套方案的适用前提是“步数已被蒸馏压到个位数、误差不再被多步平均稀释”。一旦迁到步数仍为几十步的常规扩散管线，单步量化误差会被后续迭代部分平滑，感知度量与重建度量的解耦收益随之收窄，此时按模块搜索比特的边际价值下降，直接沿用统一低位宽加少量敏感层回退更划算。迁到 DiT 主干时，模块粒度需要从“UNet 下采样块”重划为“注意力与前馈分离配置”：注意力的激活峰值随序列长度平方增长，权重量化省下的显存容易被激活吃掉，预算约束 <span class=\"formula\">$$\\sum_l \\text{mem}(b_l)\\le M$$</span> 中的 mem 必须显式区分权重项与激活项，否则搜索会给出“权重压得很低、激活仍溢出”的配置。迁到视频或多帧生成，时间维度的中间激活按帧累积，逐层反量化的访存节省被激活带宽需求抵消，方案退化为单纯的权重压缩，收益上限由权重体积而非峰值显存决定。</p>\n<p>失效条件集中在三处。其一，λ 的取值决定感知与重建的折中方向，材料未给出取值，迁到对文字渲染或人脸细节敏感的领域时，感知度量若未覆盖这些区域，搜索会把文本编码器或浅层主干压到过低比特，条件保真度先崩。其二，VAE 解码的峰值显存若不纳入同一预算，只压主干会在解码阶段触发溢出，量化省下的显存无法转化为批大小，吞吐收益归零。其三，极低位宽（材料未给出 2 bit 的失效边界）下逐层反量化的额外开销可能超过访存节省，单步延迟不降反升，这在个位数步数、单请求计算量本就很小的场景里直接体现为尾延迟恶化。</p>\n<table class=\"mini\"><thead><tr><th>迁移目标</th><th>需改动</th><th>系统代价</th></tr></thead><tbody><tr><td>多步扩散管线</td><td>弱化解耦搜索，改统一位宽+敏感层回退</td><td>搜索开销省下，显存压缩率下降</td></tr><tr><td>DiT 主干</td><td>注意力/前馈分开配比特，激活项入预算</td><td>激活峰值主导，权重节省被摊薄</td></tr><tr><td>视频/多帧</td><td>按帧核算激活，反量化开销需实测</td><td>带宽而非容量成为瓶颈</td></tr></tbody></table>\n<p>规模上限的判断落在服务端拓扑上：方案本身不含并行切分与低精度算子选型，迁到 B200/GB200 NVL72 多卡部署时，逐层反量化的算子若不被 tcgen05 路径原生支持，反量化会插入额外内核，破坏融合矩阵乘的流水，单卡吞吐提升被通信与内核启动开销吃掉。CFG 正负分支合并成批能摊薄权重读取，但批大小受 VAE 解码峰值约束，量化省出的显存应先给解码阶段的并发而非无脑加批。可迁移的是“按模块敏感度分配比特、预算覆盖解码峰值”这一配置框架；不可迁移的是具体位宽表——它依赖校准集分布与目标领域的感知度量，换领域必须重跑搜索，且需以 NVFP4/FP8 原生格式为候选集重新标定，材料未给出该对照，落地前应以实测的单步延迟与显存峰值为准决定是否回退敏感层。</p>\n<figure class=\"diagram\" data-fig=\"paper-family\"><svg style=\"max-width:746px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 746.0 138\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><text x=\"136.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">上游 · 站在谁肩上</text><rect x=\"38.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><text x=\"48.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#b45309\" font-weight=\"500\" text-anchor=\"start\">领域入口（无上游）</text><text x=\"380.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">本文</text><rect x=\"282.0\" y=\"44.0\" width=\"196.0\" height=\"52.0\" rx=\"6\" fill=\"#e9eff5\" stroke=\"#d6e2ec\" stroke-width=\"1.2\"/><text x=\"292.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\">MixDQ: Memory-Efficient </text><text x=\"292.0\" y=\"78.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\">Few-Step Text-t…</text><text x=\"624.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">下游 · 被谁接走</text><rect x=\"526.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><text x=\"536.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#15803d\" font-weight=\"500\" text-anchor=\"start\">暂无下游记录</text><line x1=\"238.0\" y1=\"74.0\" x2=\"271.0\" y2=\"74.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 270.0 69.5 L 270.0 78.5 L 278.0 74.0 Z\" fill=\"#d8d3c6\"/><line x1=\"482.0\" y1=\"74.0\" x2=\"515.0\" y2=\"74.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 514.0 69.5 L 514.0 78.5 L 522.0 74.0 Z\" fill=\"#d8d3c6\"/><text x=\"380.0\" y=\"128.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.0\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"middle\">2024 · arXiv preprint</text></svg><figcaption><b>家谱</b> · MixDQ: Memory-Efficient… 的上游问题、本文位置与下游继承；箭头表示方法/问题的传递，不是时间先后。</figcaption></figure>\n<table class=\"mini\" data-fig=\"paper-exp\"><caption>实验速查：这篇论文拿什么数据、和谁比、提升来自哪里</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>数据集</td><td>文本到图像生成基准（材料未给出具体数据集名称）</td></tr><tr><td>基线</td><td>统一精度量化方案（材料未给出具体基线名称与数字）</td></tr><tr><td>主要结果</td><td>材料未给出可核验的定量结果，包括 FID、CLIP 分数、显存占用与吞吐数…</td></tr><tr><td>消融</td><td>材料未给出消融实验的具体设置与数字；可推断的消融维度包括度量解耦项的相对权…</td></tr><tr><td>局限</td><td>材料未给出实验规模、硬件档位与评测协议细节；少步采样下误差累积的定量分析、…</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：papers/paper-mixdq-memory-efficient-few-step-text-2024 · 共 9 个片段</p>\n";break;}}})();
